package bolo

import (
	"chain"
	"chain/runtime"
)

// Close closes campaign id to new donations. Its organizer can, at any time; anyone
// can, once it is past its deadline or inactive for long enough — the campaign's page
// says when. Closing stops gifts only: what the campaign holds still goes to the
// beneficiary, or back to its donors.
//
// Its branch follows state, never the caller (API §3.1, Q7). Past its deadline, Close
// records the close if nothing has yet, and never fails. A dormant campaign closes as
// dormant, whoever calls. Only an open campaign nobody else may close yet takes the
// organizer's branch, which checks how the call arrived (C11) before it reads who
// sent it.
func Close(cur realm, id string) {
	assertCurrent(cur)
	c := campaignOf(id)
	recordDeadline(cur, c)
	if c.deadline != 0 && now() >= c.deadline {
		return // recorded above, now or before: housekeeping, never an error
	}
	assertOpen(c)
	if now() >= dormantAt(c) {
		closeNow(c, reasonDormant, cur.Previous().Address())
		return
	}
	if !cur.Previous().IsUserCall() {
		panic(ErrNotUserCall)
	}
	runtime.AssertOriginCall()
	if cur.Previous().Address() != c.organizer {
		panic(ErrNotClosable)
	}
	closeNow(c, reasonOrganizer, c.organizer)
}

// closeNow closes the open campaign c now, for reason, and takes it out of the
// active indexes; Closed names by, who sent the call (API §3.1, §6).
func closeNow(c *campaign, reason string, by address) {
	s := c.state
	s.status, s.closedAt, s.closeReason = statusClosed, now(), reason
	stats.open--
	dropActive(c)
	chain.Emit(evClosed, "id", idString(c.id), "reason", reason, "by", by.String())
}

// closeNotYet is CanClose's reason while only the organizer may close.
const closeNotYet = "not_yet"

// CanClose says what Close(id), sent by caller from a wallet, would do now (API
// §4): true, with the reason it would record — "deadline" or "dormant" for anyone,
// "organizer" for the organizer alone — or false, with "closed" once closed or
// settled, and "not_yet" while only the organizer may close.
func CanClose(id string, caller address) (bool, string) {
	c := campaignOf(id)
	status, _, _ := effective(c)
	switch {
	case status != statusOpen && c.state.status == statusOpen:
		return true, reasonDeadline // passed, not yet recorded
	case status != statusOpen:
		return false, statusClosed
	case now() >= dormantAt(c):
		return true, reasonDormant
	case caller == c.organizer:
		return true, reasonOrganizer
	}
	return false, closeNotYet
}

package bolo

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
)

// TestClose walks each of Close's branches. Before each call, CanClose names the
// reason Close then records (API §4); the refusals are in txtar (organizer.txtar).
func TestClose(cur realm, t *testing.T) {
	closed := func(c *campaign, reason string, at int64) bool {
		s := c.state
		return s.status == statusClosed && s.closeReason == reason && s.closedAt == at && !active.Has(c.id.Binary()) &&
			!activeByCategory.Has(c.category+"/"+c.id.Binary())
	}

	// The organizer closes an open campaign, now.
	c := testCampaign(9201, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	if ok, why := CanClose(id, c.organizer); !ok || why != reasonOrganizer {
		t.Errorf("CanClose(organizer) = %t, %q", ok, why)
	}
	testing.SetRealm(testing.NewUserRealm(c.organizer))
	Close(cross(cur), id)
	if !closed(c, reasonOrganizer, now()) {
		t.Errorf("organizer: %v", *c.state)
	}
	if ok, why := CanClose(id, c.organizer); ok || why != statusClosed {
		t.Errorf("CanClose once closed = %t, %q", ok, why)
	}

	// Past dormancy, anyone closes it for dormancy, its organizer too (Q7).
	d := testCampaign(9202, modeEscrow, 0)
	idD, unstoreD := storeCampaign(d)
	defer unstoreD()
	e := testCampaign(9203, modeEscrow, 0)
	idE, unstoreE := storeCampaign(e)
	defer unstoreE()
	testing.SkipHeights(90 * heightsPerDay)
	if ok, why := CanClose(idD, passerby); !ok || why != reasonDormant {
		t.Errorf("CanClose(passerby), dormant = %t, %q", ok, why)
	}
	testing.SetRealm(testing.NewUserRealm(passerby))
	Close(cross(cur), idD)
	if !closed(d, reasonDormant, now()) {
		t.Errorf("passerby, dormant: %v", *d.state)
	}
	if ok, why := CanClose(idE, e.organizer); !ok || why != reasonDormant {
		t.Errorf("CanClose(organizer), dormant = %t, %q", ok, why)
	}
	testing.SetRealm(testing.NewUserRealm(e.organizer))
	Close(cross(cur), idE)
	if !closed(e, reasonDormant, now()) {
		t.Errorf("organizer, dormant: %v", *e.state)
	}

	// Past its deadline: closed at the deadline by whoever calls first; a second
	// call changes nothing, and fails nothing.
	f := testCampaign(9204, modeEscrow, now()+2*secondsPerDay)
	idF, unstoreF := storeCampaign(f)
	defer unstoreF()
	g := testCampaign(9205, modeEscrow, now()+2*secondsPerDay)
	idG, unstoreG := storeCampaign(g)
	defer unstoreG()
	testing.SetRealm(testing.NewUserRealm(g.organizer))
	Close(cross(cur), idG)
	closedG := now()
	testing.SkipHeights(3 * heightsPerDay)
	if ok, why := CanClose(idF, passerby); !ok || why != reasonDeadline {
		t.Errorf("CanClose(passerby), deadline = %t, %q", ok, why)
	}
	testing.SetRealm(testing.NewUserRealm(passerby))
	Close(cross(cur), idF)
	if !closed(f, reasonDeadline, f.deadline) {
		t.Errorf("passerby, deadline: %v", *f.state)
	}
	Close(cross(cur), idF)
	if !closed(f, reasonDeadline, f.deadline) {
		t.Errorf("a second close changed it: %v", *f.state)
	}
	// One the organizer closed before its deadline keeps its close after it.
	Close(cross(cur), idG)
	if !closed(g, reasonOrganizer, closedG) {
		t.Errorf("closed before its deadline, then housekept: %v", *g.state)
	}
}

// TestDormancy: dormancy counts from the latest of creation, the last gift and the
// last update, so an update resets it (API §3.1).
func TestDormancy(cur realm, t *testing.T) {
	c := testCampaign(9206, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	testing.SkipHeights(80 * heightsPerDay)
	testing.SetRealm(testing.NewUserRealm(c.organizer))
	PostUpdate(cross(cur), id, "Still here.")
	testing.SkipHeights(90*heightsPerDay - 1)
	if ok, why := CanClose(id, passerby); ok || why != closeNotYet {
		t.Errorf("a height before 90 days from the update: %t, %q", ok, why)
	}
	testing.SkipHeights(1)
	if ok, why := CanClose(id, passerby); !ok || why != reasonDormant {
		t.Errorf("90 days from the update: %t, %q", ok, why)
	}
	c.state.lastDonationAt = now()
	if ok, why := CanClose(id, passerby); ok || why != closeNotYet {
		t.Errorf("right after a gift: %t, %q", ok, why)
	}
}

func TestCanClose(t *testing.T) {
	organizer := testutils.TestAddress("organizer")
	open := testCampaign(9211, modeEscrow, 0)
	dormant := testCampaign(9212, modeEscrow, 0)
	dormant.createdAt = now() - 90*secondsPerDay
	passed := testCampaign(9213, modeEscrow, now()-1)
	both := testCampaign(9214, modeEscrow, now()-1)
	both.createdAt = now() - 91*secondsPerDay
	recorded := testCampaign(9215, modeEscrow, now()-1)
	recorded.state.status = statusClosed
	shut := testCampaign(9216, modeEscrow, 0)
	shut.state.status = statusClosed
	settled := testCampaign(9217, modeEscrow, 0)
	settled.state.status = statusSettled
	for _, k := range []struct {
		name   string
		c      *campaign
		caller address
		ok     bool
		why    string
	}{
		{"open, organizer", open, organizer, true, reasonOrganizer},
		{"open, passerby", open, passerby, false, closeNotYet},
		{"dormant, passerby", dormant, passerby, true, reasonDormant},
		{"dormant, organizer", dormant, organizer, true, reasonDormant},
		{"deadline passed, unrecorded", passed, passerby, true, reasonDeadline},
		{"deadline passed and dormant", both, organizer, true, reasonDeadline},
		{"deadline recorded", recorded, passerby, false, statusClosed},
		{"closed", shut, organizer, false, statusClosed},
		{"settled", settled, organizer, false, statusClosed},
	} {
		id, unstore := storeCampaign(k.c)
		ok, why := CanClose(id, k.caller)
		unstore()
		if ok != k.ok || why != k.why {
			t.Errorf("%s: CanClose = %t, %q, want %t, %q", k.name, ok, why, k.ok, k.why)
		}
	}
	if !panicsWith(func() { CanClose("042", organizer) }, ErrNotFound) {
		t.Errorf("CanClose(\"042\"): not ErrNotFound")
	}
}

package bolo

import (
	"chain"
	"chain/banker"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// maxDeadlineDays bounds how far ahead a deadline may be, so no timer computed from
// it can overflow (API §3.1).
const maxDeadlineDays = 3650

// CreateCampaign opens a campaign, which you organize, and returns its ID. Send the
// creation deposit with it — Bolo's "Start a campaign" link attaches it — and it comes
// back when the campaign completes. title and description are public, and the
// description may hold links, never an image. category is one of Bolo's categories.
// imageCID and imageAlt are a photo on IPFS and what it shows, or both empty.
// beneficiary is the address the money goes to, which can never change. goal is in
// ugnot, 0 for none. mode is "escrow" or "direct". deadline is a Unix time, 0 for
// none.
//
// It opens a campaign for its caller, the organizer (API §3.1). The envelope is
// exactly the creation deposit, which goes to the campaign's bond address: the realm
// keeps nothing (INV-3).
func CreateCampaign(cur realm, title, description, category, imageCID, imageAlt string, beneficiary address, goal int64, mode string, deadline int64) string {
	assertCurrent(cur)
	if !cur.Previous().IsUserCall() {
		panic(ErrNotUserCall)
	}
	runtime.AssertOriginCall()
	if envelopeUgnot() != params.CreationDeposit {
		panic(ErrDepositMismatch)
	}
	if paused {
		panic(ErrPaused)
	}
	if sunset {
		panic(ErrSunset)
	}
	text := checkCampaignText(title, description, imageCID, imageAlt)
	checkCampaignTerms(category, mode, goal, deadline)
	checkBeneficiary(beneficiary, nextID+1)

	id := nextID.Next()
	c := &campaign{
		id:          id,
		category:    category,
		organizer:   cur.Previous().Address(),
		beneficiary: beneficiary,
		mode:        mode,
		goal:        goal,
		deadline:    deadline,
		createdAt:   now(),
		params:      params,

		text:  text,
		state: &campaignState{status: statusOpen, listed: true},

		contributions: avl.NewTree(),
		receipts:      avl.NewTree(),
		withdrawals:   avl.NewTree(),
		refunds:       avl.NewTree(),
		updates:       avl.NewTree(),
	}
	key := id.Binary()
	campaigns.Set(key, c)
	stats.open++
	derived.Set(escrowAddr(id).String(), true)
	derived.Set(bondAddr(id).String(), true)
	addActive(c)
	byOrganizer.Set(c.organizer.String()+"/"+key, true)
	byBeneficiary.Set(beneficiary.String()+"/"+key, true)

	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(realmAddr(), bondAddr(id), chain.NewCoins(chain.NewCoin("ugnot", c.params.CreationDeposit)))
	chain.Emit(evCampaignCreated,
		"id", idString(id),
		"organizer", c.organizer.String(),
		"beneficiary", beneficiary.String(),
		"mode", mode,
		"category", category,
		"goal", itoa(goal),
		"deadline", itoa(deadline),
	)
	return idString(id)
}

// checkCampaignText checks a campaign's text (API §2.3) and returns it normalized:
// the title, the story, and the photo with its description.
func checkCampaignText(title, description, imageCID, imageAlt string) *campaignText {
	title = checkText(title, titleMin, titleMax, false, ErrTitle)
	description = checkStory(description, 0, descriptionMax, ErrDescription)
	imageCID, imageAlt = checkImage(imageCID, imageAlt)
	return &campaignText{title: title, description: description, imageCID: imageCID, imageAlt: imageAlt}
}

// checkCampaignTerms refuses a category not listed, a mode that isn't one, a
// negative goal, and a deadline neither 0 nor in the future, at most maxDeadlineDays
// ahead (API §3.1).
func checkCampaignTerms(category, mode string, goal, deadline int64) {
	if !categories.Has(category) {
		panic(ErrCategory)
	}
	if mode != modeDirect && mode != modeEscrow {
		panic(ErrMode)
	}
	if goal < 0 {
		panic(ErrGoal)
	}
	if deadline != 0 && (deadline <= now() || deadline > now()+maxDeadlineDays*secondsPerDay) {
		panic(ErrDeadline)
	}
}

// checkBeneficiary refuses a malformed address (C12) and every address a campaign
// must never pay (API §1): the realm's, slashed, the storage-deposit address, the
// registry and its storage-deposit address, every escrow and bond address handed
// out — and those of id, the campaign about to be created, which paying itself
// would trap every gift.
func checkBeneficiary(b address, id seqid.ID) {
	checkAddress(b, ErrBeneficiary)
	if b == realmAddr() || b == slashedAddr() || b == depositAddr() || b == registryAddr() || b == registryDepositAddr() ||
		derived.Has(b.String()) || b == escrowAddr(id) || b == bondAddr(id) {
		panic(ErrBeneficiary)
	}
}

package bolo

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
)

// TestCreateCampaign creates campaigns as a user, straight from the test's body as
// AssertOriginCall requires (plan §3.3), with the envelope and the realm's coins a
// real transaction would bring. Its refusals are in txtar (create.txtar): a test
// can't recover a crossing call's panic.
func TestCreateCampaign(cur realm, t *testing.T) {
	defer restoreCampaigns(nextID)
	defer restoreSettings(admin, pendingAdmin, params, presets, minDonation, escrowCap, tipRecipient, paused, sunset, categoryOrder)

	organizer := testutils.TestAddress("organizer")
	beneficiary := testutils.TestAddress("beneficiary")
	deposit := params.CreationDeposit
	first := nextID + 1

	testing.SetRealm(testing.NewUserRealm(organizer))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", deposit)))
	testing.IssueCoins(realmAddr(), chain.NewCoins(chain.NewCoin("ugnot", deposit)))
	id := CreateCampaign(cross(cur), "  Clean water for Ndiaganiao ", "A pump.", "water", "", "", beneficiary, 1_500_000_000, modeEscrow, 0)
	if id != idString(first) {
		t.Fatalf("CreateCampaign returned %q, want %q", id, idString(first))
	}

	// The deposit went to the bond address; the realm keeps nothing (INV-3).
	rb := banker.NewReadonlyBanker()
	if got := rb.GetCoin(bondAddr(first), "ugnot"); got != deposit {
		t.Errorf("bond address holds %d, want the deposit %d", got, deposit)
	}
	if got := rb.GetCoin(realmAddr(), "ugnot"); got != 0 {
		t.Errorf("the realm kept %d", got)
	}

	v := GetCampaign(id)
	want := CampaignView{
		ID: id, Title: "Clean water for Ndiaganiao", Description: "A pump.", Category: "water",
		Organizer: organizer, Beneficiary: beneficiary, Mode: modeEscrow, Status: statusOpen, Listed: true,
		Goal: 1_500_000_000, Deposit: deposit, CreatedAt: now(),
		ClosableByAnyoneAt: now() + params.DormancyPeriod,
		EscrowAddress:      escrowAddr(first), BondAddress: bondAddr(first), Params: params,
	}
	if v != want {
		t.Errorf("GetCampaign =\n%v\nwant\n%v", v, want)
	}
	key := first.Binary()
	for name, tree := range map[string]*avl.Tree{
		"campaigns":        &campaigns,
		"active":           &active,
		"activeByCategory": &activeByCategory,
		"byOrganizer":      &byOrganizer,
		"byBeneficiary":    &byBeneficiary,
	} {
		k := key
		switch name {
		case "activeByCategory":
			k = "water/" + key
		case "byOrganizer":
			k = organizer.String() + "/" + key
		case "byBeneficiary":
			k = beneficiary.String() + "/" + key
		}
		if !tree.Has(k) {
			t.Errorf("campaign %s is missing from %s", id, name)
		}
	}
	if !derived.Has(escrowAddr(first).String()) || !derived.Has(bondAddr(first).String()) {
		t.Errorf("campaign %s's escrow and bond addresses aren't recorded as derived", id)
	}

	// A change of Params applies to campaigns created afterwards only (INV-5).
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	SetParams(cross(cur), 3_000_000, 30, 14, 7)
	testing.SetRealm(testing.NewUserRealm(organizer))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 3_000_000)))
	testing.IssueCoins(realmAddr(), chain.NewCoins(chain.NewCoin("ugnot", 3_000_000)))
	second := CreateCampaign(cross(cur), "A second campaign", "", "food", "", "", beneficiary, 0, modeDirect, 0)
	if v := GetCampaign(id); v.Params != want.Params || v.Deposit != deposit {
		t.Errorf("SetParams changed campaign %s: %v", id, v.Params)
	}
	if v := GetCampaign(second); v.Params != GetParams() || v.Deposit != 3_000_000 {
		t.Errorf("campaign %s didn't get the new Params: %v", second, v.Params)
	}
}

func TestCheckCampaignTerms(t *testing.T) {
	checkCampaignTerms("water", modeDirect, 0, 0)
	checkCampaignTerms("water", modeEscrow, 1, now()+1)
	checkCampaignTerms("water", modeEscrow, 1, now()+maxDeadlineDays*secondsPerDay)
	for name, c := range map[string]struct {
		category, mode string
		goal, deadline int64
		err            Error
	}{
		"unknown category":  {"rockets", modeDirect, 0, 0, ErrCategory},
		"no mode":           {"water", "", 0, 0, ErrMode},
		"unknown mode":      {"water", "both", 0, 0, ErrMode},
		"negative goal":     {"water", modeDirect, -1, 0, ErrGoal},
		"deadline now":      {"water", modeDirect, 0, now(), ErrDeadline},
		"deadline past":     {"water", modeDirect, 0, now() - 1, ErrDeadline},
		"deadline too far":  {"water", modeDirect, 0, now() + maxDeadlineDays*secondsPerDay + 1, ErrDeadline},
		"deadline negative": {"water", modeDirect, 0, -1, ErrDeadline},
	} {
		if !panicsWith(func() { checkCampaignTerms(c.category, c.mode, c.goal, c.deadline) }, c.err) {
			t.Errorf("%s: not refused with %s", name, c.err)
		}
	}
}

func TestCheckCampaignText(t *testing.T) {
	text := checkCampaignText(" Clean water ", " A pump. ", "", "")
	if text.title != "Clean water" || text.description != "A pump." {
		t.Errorf("checkCampaignText = %v", text)
	}
	for name, c := range map[string]struct {
		title, description, cid, alt string
		err                          Error
	}{
