package bolo

import "chain/runtime/unsafe"

// envelopeUgnot returns the ugnot attached to this call (API C3, C4): an envelope is
// one ugnot coin, or nothing; anything else is ErrWrongDenom. It is the one place
// Bolo reads OriginSend, and only user-only writes reach it: C11's keyed refusal, then
// AssertOriginCall, in their own body (make check). Never a write behind C11's realm
// branch, which a deployed realm passes with an envelope paid to itself.
func envelopeUgnot() int64 {
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		return 0
	}
	if len(sent) > 1 || sent[0].Denom != "ugnot" {
		panic(ErrWrongDenom)
	}
	return sent[0].Amount
}

package bolo

import (
	"chain"
	"chain/banker"
)

// Finalize completes closed campaign id: anyone can, once the campaign's page offers
// it. It returns the organizer's deposit, and sends the beneficiary the coins someone
// sent to the escrow outside Bolo. What donors can still reclaim stays theirs.
//
// It settles a closed campaign, and forwards what no donor is owed (API §3.4): anyone
// may call, with no identity. At its first call it settles the campaign;
// every call forwards the coins sent to the escrow outside Bolo to the beneficiary,
// and everything at the bond address but a bond still on hold to the organizer — the
// deposit, and the bond once its hold has ended. It never moves the tracked balance:
// that stays the donors' (INV-16).
func Finalize(cur realm, id string) {
	assertCurrent(cur)
	c := campaignOf(id)
	recordDeadline(cur, c)
	f := bookFinalize(c)
	if f.toBeneficiary > 0 {
		banker.NewBanker(banker.BankerTypeRealmSend, escrowSub(cur, c)).SendCoins(escrowAddr(c.id), c.beneficiary, chain.NewCoins(chain.NewCoin("ugnot", f.toBeneficiary)))
	}
	if f.toOrganizer > 0 {
		banker.NewBanker(banker.BankerTypeRealmSend, bondSub(cur, c)).SendCoins(bondAddr(c.id), c.organizer, chain.NewCoins(chain.NewCoin("ugnot", f.toOrganizer)))
	}
	if f.settled {
		chain.Emit(evSettled, "id", idString(c.id), "toOrganizer", itoa(f.toOrganizer), "toBeneficiary", itoa(f.toBeneficiary))
	}
	if f.released > 0 {
		chain.Emit(evBondReleased, "id", idString(c.id), "amount", itoa(f.released), "to", c.organizer.String())
	}
}

// settlement is what one Finalize call moves, and announces.
type settlement struct {
	toBeneficiary int64 // the untracked coins at the escrow
	toOrganizer   int64 // everything at the bond address but a bond still on hold
	released      int64 // the bond this call releases, or 0
	settled       bool  // this call settles the campaign
}

// bookFinalize checks a Finalize call on c and enters it in the books, before any coin
// moves (API §3.4): the first settles c, if checkFinalizable allows; every one works
// out what to forward, and releases a bond whose hold has ended.
func bookFinalize(c *campaign) settlement {
	s := c.state
	settled := false
	if s.status != statusSettled {
		checkFinalizable(c)
		s.status = statusSettled
		stats.settled++
		settled = true
	}
	f := pending(c)
	f.settled = settled
	if f.released > 0 {
		s.bondReleased = true
	}
	return f
}

// checkFinalizable refuses c's first settlement (API §3.4), with ErrNotFinalizable,
// unless it is closed and its FinalizableAt has come: at once in direct mode or with
// no tracked balance, else once its exit window opens. The view, CanFinalize and this
// share one rule, finalizableAt.
func checkFinalizable(c *campaign) {
	s := c.state
	if s.status != statusClosed {
		panic(ErrNotFinalizable)
	}
	if now() < finalizableAt(c, s.closedAt, trackedBalance(c)) {
		panic(ErrNotFinalizable)
	}
}

// pending works out what a Finalize call would move from c now, without writing: the
// escrow's coins above its books, to the beneficiary; the bond address's coins but a
// bond still on hold — not slashed, not released, its hold not ended — to the
// organizer, the bond itself included once its hold has ended. Books above the bank,
// at either address, are ErrBooksMismatch (INV-1, INV-7).
func pending(c *campaign) settlement {
	s := c.state
	var f settlement
	f.toBeneficiary = banker.NewReadonlyBanker().GetCoin(escrowAddr(c.id), "ugnot") - trackedBalance(c)
	held := int64(0)
	if s.bond > 0 && !s.bondSlashed && !s.bondReleased {
		if now() >= s.closedAt+c.params.BondHold {
			f.released = s.bond
		} else {
			held = s.bond
		}
	}
	f.toOrganizer = banker.NewReadonlyBanker().GetCoin(bondAddr(c.id), "ugnot") - held
	if f.toBeneficiary < 0 || f.toOrganizer < 0 {
		panic(ErrBooksMismatch)
	}
	return f
}

// CanFinalize says what Finalize(id) would do now (API §4), a passed deadline counted
// as recorded: true with "settle" for the first settlement, or "forward" on a settled
// campaign with something to move; false with "open", "not_yet" while a tracked balance
// waits for its exit window, or "settled" with nothing to move.
func CanFinalize(id string) (bool, string) {
	c := campaignOf(id)
	status, _, closedAt := effective(c)
	switch status {
	case statusOpen:
		return false, statusOpen
	case statusClosed:
		if now() < finalizableAt(c, closedAt, trackedBalance(c)) {
			return false, "not_yet"
		}
		return true, "settle"
	}
	if f := pending(c); f.toBeneficiary > 0 || f.toOrganizer > 0 {
		return true, "forward"
	}
	return false, statusSettled
}

package bolo

import (
	"math"
	"time"
)

// assertCurrent is the first statement of every crossing function (API C2).
func assertCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("bolo: not the current realm")
	}
}

// checkAddress refuses an address argument that isn't a well-formed address (API
// C12): exactly 40 characters, a lowercase "g" first, then IsValid(). MsgCall
// passes an address argument through unchecked, and a malformed one stored once
// would make every later send to it fail. IsValid alone also accepts an address in
// capitals, which the bank pays as the same account but which never equals the
// lowercase spelling; it refuses mixed case, so a lowercase "g" means a lowercase
// address. The length comes first, so IsValid only ever parses address-sized
// input.
func checkAddress(a address, err Error) {
	if len(a) != 40 || a[0] != 'g' || !a.IsValid() {
		panic(err)
	}
}

const secondsPerDay = 24 * 60 * 60

// daysToSeconds converts a duration in whole days to seconds, refusing a negative
// one and one whose seconds would overflow (API §2.3).
func daysToSeconds(days int, err Error) int64 {
	if days < 0 || int64(days) > math.MaxInt64/secondsPerDay {
		panic(err)
	}
	return int64(days) * secondsPerDay
}

// now is block time in Unix seconds (API C8).
func now() int64 { return time.Now().Unix() }

package bolo

import (
	"math"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func TestCheckAddress(t *testing.T) {
	good := testutils.TestAddress("beneficiary")
	checkAddress(good, ErrBeneficiary)

	bad := string(good)
	last := "q"
	if bad[39] == 'q' {
		last = "p"
	}
	for name, a := range map[string]address{
		"empty":        "",
		"39 chars":     address(bad[:39]),
		"41 chars":     address(bad + "q"),
		"bad checksum": address(bad[:39] + last),
		"not bech32":   address("0x00000000000000000000000000000000000000"),
		// IsValid takes an address in capitals, as the same account; it must not
		// pass as a second address (API C12). Mixed case is refused by IsValid.
		"capitals":   address(strings.ToUpper(bad)),
		"mixed case": address(bad[:20] + strings.ToUpper(bad[20:])),
	} {
		if !panicsWith(func() { checkAddress(a, ErrBeneficiary) }, ErrBeneficiary) {
			t.Errorf("%s: not refused", name)
		}
	}
}

func TestDaysToSeconds(t *testing.T) {
	if got := daysToSeconds(0, ErrSetting); got != 0 {
		t.Errorf("0 days = %d", got)
	}
	if got := daysToSeconds(3650, ErrSetting); got != 315360000 {
		t.Errorf("3650 days = %d", got)
	}
	for _, days := range []int{-1, math.MaxInt64/secondsPerDay + 1, math.MaxInt64} {
		if !panicsWith(func() { daysToSeconds(days, ErrSetting) }, ErrSetting) {
			t.Errorf("%d days: not refused", days)
		}
	}
}

func TestNow(t *testing.T) {
	start := now()
	testing.SkipHeights(12)
	if got := now() - start; got != 60 {
		t.Errorf("12 heights moved now() by %d seconds, want 60", got)
	}
}

package bolo

// panicsWith reports whether f panics with err.
func panicsWith(f func(), err Error) (ok bool) {
	defer func() {
		r := recover()
		e, isErr := r.(Error)
		ok = isErr && e == err
	}()
	f()
	return false
}

package bolo

import (
	"strconv"

	"gno.land/p/nt/seqid/v0"
)

// parseID returns the campaign ID s names, if s is canonical (API C9): the
// decimal form of a positive ID — digits only, no sign, no leading zero, no
// space. "042" names nothing, never campaign 42: one ID has one spelling, and so
// one set of addresses (INV-18).
func parseID(s string) (seqid.ID, bool) {
	if len(s) == 0 || len(s) > 20 || s[0] == '0' {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return seqid.ID(n), true
}

// idString is the canonical decimal form of id.
func idString(id seqid.ID) string {
	return strconv.FormatUint(uint64(id), 10)
}

package bolo

import "testing"

func TestParseID(t *testing.T) {
	for _, s := range []string{"1", "7", "42", "18446744073709551615"} {
		id, ok := parseID(s)
		if !ok || idString(id) != s {
			t.Errorf("parseID(%q) = %d, %t; want %s", s, uint64(id), ok, s)
		}
	}
	// One ID, one spelling (API C9, INV-18): anything else names no campaign.
	for _, s := range []string{
		"", "0", "00", "042", "+42", "-1", " 42", "42 ", "4 2", "4.2", "0x2a", "1e3",
		"18446744073709551616", "99999999999999999999", "123456789012345678901",
		"４２", "٤٢",
	} {
		if id, ok := parseID(s); ok {
			t.Errorf("parseID(%q) = %d; want no campaign", s, uint64(id))
		}
	}
}

package bolo

// init refuses to deploy Bolo from its admin's own key (API §3.6, ADR D11). The
// key that deploys under the namespace must not also be the admin: one stolen key
// could otherwise deploy a malicious version and point the registry at it. Then it
// lists the launch categories for lookups (API §2.1).
func init(cur realm) {
	if cur.Previous().Address() == adminAddr {
		panic("bolo: the admin key may not deploy Bolo; deploy from the namespace key, which must not be the admin")
	}
	for _, code := range categoryOrder {
		categories.Set(code, true)
	}
}

package bolo

import "gno.land/p/nt/avl/v0"

// Lists (API §4). A size is clamped to 1–50 (INV-9). The campaign lists page by
// cursor: each reaches its place in its index by key, in O(log n), never by counting
// entries. The per-campaign lists page by number, by offset in the campaign's own tree.

const maxPageSize = 50

// idKeyLen is the length of a campaign's key, seqid.ID.Binary().
const idKeyLen = 8

// pageSize clamps a requested size to 1–50.
func pageSize(size int) int {
	if size < 1 {
		return 1
	}
	if size > maxPageSize {
		return maxPageSize
	}
	return size
}

// ListCampaigns returns the open, listed campaigns, newest first, from below after (""
// for the newest), and the cursor to pass next, "" at the end; category may be "".
// A campaign past a deadline nobody recorded is left out (Q6). One call reads at most
// four times size entries, so a page can be short while the cursor isn't "".
func ListCampaigns(after string, size int, category string) ([]CampaignView, string) {
	size = pageSize(size)
	index, prefix := &active, ""
	if category != "" {
		index, prefix = &activeByCategory, category+"/"
	}
	return campaignPage(index, prefix, after, size, 4*size, func(c *campaign) bool {
		status, _, _ := effective(c)
		return status == statusOpen
	})
}

// ListByOrganizer returns the campaigns addr organizes, delisted included, newest
// first, from below after, and the cursor to pass next. An address is compared as
// given (C12).
func ListByOrganizer(addr address, after string, size int) ([]CampaignView, string) {
	size = pageSize(size)
	return campaignPage(&byOrganizer, addr.String()+"/", after, size, size, everyCampaign)
}

// ListByBeneficiary returns the campaigns naming addr as beneficiary, delisted included
// — the beneficiary must keep seeing them (INV-4) — newest first, from below after,
// and the cursor to pass next.
func ListByBeneficiary(addr address, after string, size int) ([]CampaignView, string) {
	size = pageSize(size)
	return campaignPage(&byBeneficiary, addr.String()+"/", after, size, size, everyCampaign)
}

// ListByDonor returns the campaigns addr gave to at least once without anonymity,
// newest first, from below after, and the cursor to pass next: a campaign where all of
// addr's gifts were anonymous is in no index under addr.
func ListByDonor(addr address, after string, size int) ([]CampaignView, string) {
	size = pageSize(size)
	return campaignPage(&byDonor, addr.String()+"/", after, size, size, everyCampaign)
}

func everyCampaign(*campaign) bool { return true }

// campaignPage reads index newest first: the keys under prefix — a category's or an
// address's range, which ends at the "/" after it, or the whole index for "" — below
// after's key. It reads at most budget entries, keeps size views of those keep
// accepts, and returns them with the ID of the last entry read when more remain, ""
// when the range is done. A non-canonical after is ErrNotFound (C9).
func campaignPage(index *avl.Tree, prefix, after string, size, budget int, keep func(*campaign) bool) ([]CampaignView, string) {
	start, end := prefix, ""
	if prefix != "" {
		end = prefix[:len(prefix)-1] + "0" // "0" sorts right after "/"
	}
	cursor := ""
	if after != "" {
		id, ok := parseID(after)
		if !ok {
			panic(ErrNotFound)
		}
		cursor = prefix + id.Binary()
		end = cursor
	}
	views := []CampaignView{}
	last, read, more := "", 0, false
	// A reverse traversal includes its end: the cursor's own entry, read last time, is
	// skipped. A key whose ID part isn't a campaign key's eight bytes stops the reading:
	// only a prefix holding "/" — an address or a category crafted to end in a key's
	// first bytes — meets one, and every key in its range is such a key, so walking on
	// would read them all, past the budget, to find nothing.
	index.ReverseIterate(start, end, func(key string, _ any) bool {
		if key == cursor {
			return false
		}
		if len(key) != len(prefix)+idKeyLen {
			return true
		}
		if len(views) == size || read == budget {
			more = true
			return true
		}
		read++
		c := campaigns.Get(key[len(prefix):]).(*campaign)
		last = idString(c.id)
		if keep(c) {
			views = append(views, campaignView(c))
		}
		return false
	})
	if !more {
		return views, ""
	}
	return views, last
}

// pageOffset returns where page starts, newest first, in a tree of n entries paged by
// size, and false past the end. A page counts from 1; below 1 reads as 1.
func pageOffset(page, size, n int) (int, bool) {
	if page < 1 {
		page = 1
	}
	if page-1 > n/size {
		return 0, false
	}
	return (page - 1) * size, true
}

// ListReceipts returns a page of the campaign's gifts, newest first.
func ListReceipts(id string, page, size int) []ReceiptView {
	c := campaignOf(id)
	size = pageSize(size)
	views := []ReceiptView{}
	if offset, ok := pageOffset(page, size, c.receipts.Size()); ok {
		c.receipts.ReverseIterateByOffset(offset, size, func(_ string, v any) bool {
			views = append(views, receiptView(c, v.(*receipt)))
			return false
		})
	}
	return views
}

// WithdrawalView is one payout to the beneficiary (API §2.4): its tracked amount and
// the coins sent outside Bolo it carried, apart.
type WithdrawalView struct {
	Seq, Amount, Untracked, At int64
	To                         address
}

// ListWithdrawals returns a page of the campaign's withdrawals, newest first.
func ListWithdrawals(id string, page, size int) []WithdrawalView {
	c := campaignOf(id)
	size = pageSize(size)
	views := []WithdrawalView{}
	if offset, ok := pageOffset(page, size, c.withdrawals.Size()); ok {
		c.withdrawals.ReverseIterateByOffset(offset, size, func(_ string, v any) bool {
			w := v.(*withdrawal)
			views = append(views, WithdrawalView{Seq: int64(w.seq), Amount: w.amount, Untracked: w.untracked, At: w.at, To: w.to})
			return false
		})
	}
	return views
}

// RefundView is one payout to a donor (API §2.4). Donor is empty when all of that
// donor's gifts to the campaign were anonymous; Kind is "open" or "exit".
type RefundView struct {
	Seq, Amount, At int64
	Donor           address
	Kind            string
}

// ListRefunds returns a page of the campaign's refunds, newest first.
func ListRefunds(id string, page, size int) []RefundView {
	c := campaignOf(id)
	size = pageSize(size)
	views := []RefundView{}
	if offset, ok := pageOffset(page, size, c.refunds.Size()); ok {
		c.refunds.ReverseIterateByOffset(offset, size, func(_ string, v any) bool {
			r := v.(*refund)
			view := RefundView{Seq: int64(r.seq), Amount: r.amount, At: r.at, Kind: r.kind}
			if k := contributionOf(c, r.donor); k != nil && k.public {
				view.Donor = r.donor
			}
			views = append(views, view)
			return false
		})
	}
	return views
}

// UpdateView is one organizer update (API §2.4).
type UpdateView struct {
	Seq, At int64
	Body    string
}

// ListUpdates returns a page of the campaign's updates, newest first.
func ListUpdates(id string, page, size int) []UpdateView {
	c := campaignOf(id)
	size = pageSize(size)
	views := []UpdateView{}
	if offset, ok := pageOffset(page, size, c.updates.Size()); ok {
		c.updates.ReverseIterateByOffset(offset, size, func(_ string, v any) bool {
			u := v.(*update)
			views = append(views, UpdateView{Seq: int64(u.seq), At: u.at, Body: u.body})
			return false
		})
	}
	return views
}

package bolo

import (
	"math"
	"strings"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
)

func TestPageSize(t *testing.T) {
	for size, want := range map[int]int{math.MinInt: 1, -5: 1, 0: 1, 1: 1, 20: 20, 50: 50, 51: 50, math.MaxInt: 50} {
		if got := pageSize(size); got != want {
			t.Errorf("pageSize(%d) = %d, want %d", size, got, want)
		}
	}
}

func TestPageOffset(t *testing.T) {
	for _, k := range []struct {
		page, size, n, want int
		ok                  bool
	}{
		{1, 10, 25, 0, true},
		{3, 10, 25, 20, true},
		{0, 10, 25, 0, true}, // below 1 reads as 1
		{-7, 10, 25, 0, true},
		{4, 10, 25, 0, false}, // past the end
		{math.MaxInt, 50, 25, 0, false},
		{1, 10, 0, 0, true}, // an empty tree has an empty first page
	} {
		got, ok := pageOffset(k.page, k.size, k.n)
		if got != k.want || ok != k.ok {
			t.Errorf("pageOffset(%d, %d, %d) = %d, %t; want %d, %t", k.page, k.size, k.n, got, ok, k.want, k.ok)
		}
	}
}

// indexCampaigns stores n campaigns, IDs first to first+n-1, as CreateCampaign leaves
// them — in campaigns and every campaign index — organized by org for ben, in the
// category "animals", and returns them with what removes them again.
func indexCampaigns(first seqid.ID, n int, org, ben address) ([]*campaign, func()) {
	var cs []*campaign
	for i := 0; i < n; i++ {
		c := testCampaign(first+seqid.ID(i), modeEscrow, 0)
		c.category, c.organizer, c.beneficiary = "animals", org, ben
		key := c.id.Binary()
		campaigns.Set(key, c)
		addActive(c)
		byOrganizer.Set(org.String()+"/"+key, true)
		byBeneficiary.Set(ben.String()+"/"+key, true)
		cs = append(cs, c)
	}
	return cs, func() {
		for _, c := range cs {
			key := c.id.Binary()
			campaigns.Remove(key)
			dropActive(c)
			byOrganizer.Remove(c.organizer.String() + "/" + key)
			byBeneficiary.Remove(c.beneficiary.String() + "/" + key)
		}
	}
}

// pageAll follows a list's cursor to its end, at most 100 calls, and returns every
// ID seen, in order, with the number of calls.
func pageAll(list func(after string) ([]CampaignView, string)) ([]string, int) {
	var ids []string
	after, calls := "", 0
	for calls < 100 {
		views, next := list(after)
		calls++
		for _, v := range views {
			ids = append(ids, v.ID)
		}
		if next == "" {
			break
		}
		after = next
	}
	return ids, calls
}

// TestListCursor: a list paged to its end by cursor returns every campaign once,
// newest first; next is "" exactly at the end (API §4).
func TestListCursor(t *testing.T) {
	org, ben := testutils.TestAddress("listorg"), testutils.TestAddress("listben")
	_, unindex := indexCampaigns(9901, 7, org, ben)
	defer unindex()
	want := "9907 9906 9905 9904 9903 9902 9901"
	for name, list := range map[string]func(string) ([]CampaignView, string){
		"ListCampaigns":     func(a string) ([]CampaignView, string) { return ListCampaigns(a, 3, "animals") },
		"ListByOrganizer":   func(a string) ([]CampaignView, string) { return ListByOrganizer(org, a, 3) },
		"ListByBeneficiary": func(a string) ([]CampaignView, string) { return ListByBeneficiary(ben, a, 3) },
	} {
		ids, calls := pageAll(list)
		if got := strings.Join(ids, " "); got != want || calls != 3 {
			t.Errorf("%s: %q in %d calls, want %q in 3", name, got, calls, want)
		}
	}
	// A full last page knows it is last: the list peeks one entry further.
	if views, next := ListByOrganizer(org, "9904", 3); len(views) != 3 || next != "" {
		t.Errorf("the last full page: %d views, next %q", len(views), next)
	}
	if views, next := ListByOrganizer(org, "", 3); len(views) != 3 || next != "9905" {
		t.Errorf("the first page: %d views, next %q", len(views), next)
	}
	for _, after := range []string{"042", "+42", " 42", "x", "9901/1"} {
		if !panicsWith(func() { ListByOrganizer(org, after, 3) }, ErrNotFound) {
			t.Errorf("after %q: not ErrNotFound", after)
		}
	}
}

// TestListCampaignsPassed (Q6): a campaign past a deadline nobody recorded is left
// out; one call reads at most four times size entries, so a page can come back short
// or empty while next isn't "", and no campaign repeats or goes missing.
func TestListCampaignsPassed(t *testing.T) {
	org, ben := testutils.TestAddress("listorg"), testutils.TestAddress("listben")
	cs, unindex := indexCampaigns(9911, 9, org, ben)
	defer unindex()
	for _, c := range cs[2:7] { // 9913–9917 are past their deadline, unrecorded
		c.deadline = now() - 1
	}
	if views, next := ListCampaigns("9918", 1, "animals"); len(views) != 0 || next != "9914" {
		t.Errorf("after 9918, size 1: %d views, next %q; want none, read up to 9914", len(views), next)
	}
	ids, _ := pageAll(func(a string) ([]CampaignView, string) { return ListCampaigns(a, 1, "animals") })
	if got := strings.Join(ids, " "); got != "9919 9918 9912 9911" {
		t.Errorf("paged to the end: %q", got)
	}
	// The other lists keep every campaign, closed and past a deadline included.
	ids, _ = pageAll(func(a string) ([]CampaignView, string) { return ListByOrganizer(org, a, 50) })
	if len(ids) != 9 {
		t.Errorf("ListByOrganizer: %d campaigns, want 9", len(ids))
	}
}

// TestListRanges: an address's range stops at the "/" after it, so an address that is
// the start of a real one finds nothing (C12); a delisted campaign stays on its
// organizer's and beneficiary's lists, off ListCampaigns; ListByDonor holds only the
// campaigns an address gave to without anonymity.
func TestListRanges(t *testing.T) {
	org, ben := testutils.TestAddress("listorg"), testutils.TestAddress("listben")
	cs, unindex := indexCampaigns(9921, 3, org, ben)
	defer unindex()
	if views, next := ListByOrganizer(address(org.String()[:20]), "", 50); len(views) != 0 || next != "" {
		t.Errorf("a prefix of the organizer's address: %d views", len(views))
	}
	if views, _ := ListByOrganizer(ben, "", 50); len(views) != 0 {
		t.Errorf("the beneficiary as organizer: %d views", len(views))
	}

	delisted := cs[1]
	delisted.state.listed = false
	dropActive(delisted)
	defer addActive(delisted) // unindex drops it again
	if views, _ := ListCampaigns("", 50, "animals"); len(views) != 2 {
		t.Errorf("ListCampaigns with one delisted: %d views", len(views))
	}
	for name, views := range map[string][]CampaignView{
		"ListByOrganizer":   first(ListByOrganizer(org, "", 50)),
		"ListByBeneficiary": first(ListByBeneficiary(ben, "", 50)),
	} {
		if len(views) != 3 || views[1].Listed || views[1].ID != "9922" {
			t.Errorf("%s: %d views, the delisted one %v", name, len(views), views[1].Listed)
		}
	}

	public, anonymous := testutils.TestAddress("listpublic"), testutils.TestAddress("listanon")
	key := public.String() + "/" + cs[0].id.Binary()
	byDonor.Set(key, true)
	defer byDonor.Remove(key)
	if views, _ := ListByDonor(public, "", 50); len(views) != 1 || views[0].ID != "9921" {
		t.Errorf("ListByDonor, a public donor: %d views", len(views))
	}
	if views, _ := ListByDonor(anonymous, "", 50); len(views) != 0 {
		t.Errorf("ListByDonor, a donor whose gifts were all anonymous: %d views", len(views))
	}
}

func first(views []CampaignView, _ string) []CampaignView { return views }

// TestCampaignLists: a campaign's receipts, withdrawals, refunds and updates, newest
// first, by page number; a refund's donor blanked when all their gifts were anonymous.
func TestCampaignLists(t *testing.T) {
	c := testCampaign(9931, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	public, anonymous := testutils.TestAddress("listpublic"), testutils.TestAddress("listanon")
	c.contributions.Set(public.String(), &contribution{amount: 30, public: true})
	c.contributions.Set(anonymous.String(), &contribution{amount: 20})
	for i := 1; i <= 5; i++ {
		seq := seqid.ID(i)
		c.receipts.Set(seq.Binary(), &receipt{seq: uint64(i), donor: public, amount: int64(i)})
		c.withdrawals.Set(seq.Binary(), &withdrawal{seq: uint64(i), amount: int64(10 * i)})
		c.updates.Set(seq.Binary(), &update{seq: uint64(i), body: "update " + itoa(int64(i))})
	}
	c.refunds.Set(seqid.ID(1).Binary(), &refund{seq: 1, amount: 3, donor: public, kind: windowOpen})
	c.refunds.Set(seqid.ID(2).Binary(), &refund{seq: 2, amount: 2, donor: anonymous, kind: windowOpen})

	seqs := func(n []int64) string {
		var out []string
		for _, s := range n {
			out = append(out, itoa(s))
		}
		return strings.Join(out, " ")
	}
	receipts := func(page, size int) string {
		var n []int64
		for _, v := range ListReceipts(id, page, size) {
			n = append(n, v.Seq)
		}
		return seqs(n)
	}
	for _, k := range []struct {
		page, size int
		want       string
	}{
		{1, 2, "5 4"}, {2, 2, "3 2"}, {3, 2, "1"}, {4, 2, ""}, {0, 2, "5 4"}, {-1, 2, "5 4"},
		{1, 0, "5"}, {1, 1000, "5 4 3 2 1"}, {math.MaxInt, 2, ""},
	} {
		if got := receipts(k.page, k.size); got != k.want {
			t.Errorf("ListReceipts(page %d, size %d) = %q, want %q", k.page, k.size, got, k.want)
		}
	}
	if w := ListWithdrawals(id, 1, 2); len(w) != 2 || w[0].Seq != 5 || w[0].Amount != 50 {
		t.Errorf("ListWithdrawals: %v", w)
	}
	if u := ListUpdates(id, 2, 3); len(u) != 2 || u[0].Seq != 2 || u[0].Body != "update 2" {
		t.Errorf("ListUpdates, page 2: %v", u)
	}
	r := ListRefunds(id, 1, 50)
	if len(r) != 2 || r[0].Seq != 2 || r[0].Donor != "" || r[1].Donor != public || r[1].Kind != windowOpen {
		t.Errorf("ListRefunds: %v", r)
	}
}

