package bolo

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"
)

// Moderation (API §3.5): visibility, and the organizer's own bond — nothing else.
// Every write here starts with C11's realm branch, then assertSigner: the master key,
// then the admin's address, before anything is read. Then the campaign and its passed
// deadline, since a slash's window runs from closedAt. The rules live in plain
// helpers, which unit tests drive directly; the writes keep the caller checks, the
// send and the events. Withdraw, Refund and Finalize never read what is written here
// (INV-4).

// Delist takes the campaign off the active lists, with a public notice, and with slash
// moves its bond to the slashed address, where nothing ever spends it (INV-8).
// Delisting again replaces the notice, and may slash a bond not yet slashed.
func Delist(cur realm, id, notice string, slash bool) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	c := campaignOf(id)
	recordDeadline(cur, c)
	notice = checkText(notice, noticeMin, noticeMax, false, ErrNotice)
	if slash {
		bond := bookSlash(c)
		banker.NewBanker(banker.BankerTypeRealmSend, bondSub(cur, c)).SendCoins(bondAddr(c.id), slashedAddr(), chain.NewCoins(chain.NewCoin("ugnot", bond)))
	}
	s := c.state
	s.listed, s.notice = false, notice
	dropActive(c)
	chain.Emit(evDelisted, "id", idString(c.id), "notice", notice, "slashed", strconv.FormatBool(slash))
}

// bookSlash checks a slash of c's bond and enters it in the books, before the coins
// move (API §3.5), and returns what moves: the bond, never the deposit. It refuses, in
// order, no bond posted, a bond already slashed, a hold that has ended — once closed,
// BondHold after closedAt, settled or not — and a bond address holding less than the
// bond (INV-7).
func bookSlash(c *campaign) int64 {
	s := c.state
	if s.bond == 0 {
		panic(ErrNoBond)
	}
	if s.bondSlashed {
		panic(ErrBondSlashed)
	}
	if s.status != statusOpen && now() >= s.closedAt+c.params.BondHold {
		panic(ErrHoldEnded)
	}
	if banker.NewReadonlyBanker().GetCoin(bondAddr(c.id), "ugnot") < s.bond {
		panic(ErrBooksMismatch)
	}
	s.bondSlashed = true
	return s.bond
}

// Relist puts a delisted campaign back on the lists, and into the active indexes if
// it is still open (API §3.5). Its notice stays, as does a slash. Relisting a listed
// campaign changes nothing.
func Relist(cur realm, id string) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	c := campaignOf(id)
	recordDeadline(cur, c)
	s := c.state
	if s.listed {
		return
	}
	s.listed = true
	if s.status == statusOpen {
		addActive(c)
	}
	chain.Emit(evRelisted, "id", idString(c.id))
}

// SetNotice attaches a public warning to the campaign without delisting it, or clears
// it with "" (API §3.5). An unchanged notice changes nothing.
func SetNotice(cur realm, id, notice string) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	c := campaignOf(id)
	recordDeadline(cur, c)
	notice = checkNotice(c, notice)
	if notice == c.state.notice {
		return
	}
	c.state.notice = notice
	chain.Emit(evNoticeSet, "id", idString(c.id), "notice", notice)
}

// checkNotice returns notice as SetNotice stores it (API §3.5): "" clears, except on a
// delisted campaign, which keeps a public reason; any other text is normalized, 1–280
// characters. It panics with ErrNotice otherwise.
func checkNotice(c *campaign, notice string) string {
	if notice != "" {
		return checkText(notice, noticeMin, noticeMax, false, ErrNotice)
	}
	if !c.state.listed {
		panic(ErrNotice)
	}
	return ""
}

// HideMessage hides one gift's message (API §3.5): visibility only. The receipt, its
// amount and its donor stay, and so does the stored text. Hiding a hidden message, or
// a receipt without one, changes nothing.
func HideMessage(cur realm, id string, seq int64) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	c := campaignOf(id)
	recordDeadline(cur, c)
	r := receiptOf(c, seq)
	if r.message == "" || r.messageHidden {
		return
	}
	r.messageHidden = true
	chain.Emit(evMessageHidden, "id", idString(c.id), "seq", itoa(seq))
}

package bolo

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
)

// The helpers' tests come first: a write's test that panics through a crossing call
// ends the package's unit tests.

// TestBookSlash: a slash takes the bond and only the bond, once, while the campaign
// is open or within BondHold of its close, settled or not (API §3.5, INV-7).
func TestBookSlash(t *testing.T) {
	c := testCampaign(9801, modeDirect, 0)
	if !panicsWith(func() { bookSlash(c) }, ErrNoBond) {
		t.Errorf("no bond: not ErrNoBond")
	}
	testing.IssueCoins(bondAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 1000+300))) // the deposit, the bond
	c.state.bond = 300
	if got := bookSlash(c); got != 300 || !c.state.bondSlashed {
		t.Errorf("open: slashed %d, flagged %t; want the bond, 300", got, c.state.bondSlashed)
	}
	if !panicsWith(func() { bookSlash(c) }, ErrBondSlashed) {
		t.Errorf("a second slash: not ErrBondSlashed")
	}

	for i, status := range []string{statusClosed, statusSettled} {
		d := testCampaign(seqid.ID(9802+i), modeDirect, 0)
		testing.IssueCoins(bondAddr(d.id), chain.NewCoins(chain.NewCoin("ugnot", 300)))
		d.state.bond, d.state.status, d.state.closedAt = 300, status, now()-d.params.BondHold
		if !panicsWith(func() { bookSlash(d) }, ErrHoldEnded) {
			t.Errorf("%s, the hold just ended: not ErrHoldEnded", status)
		}
		d.state.closedAt++
		if got := bookSlash(d); got != 300 {
			t.Errorf("%s, a second before the hold ends: slashed %d", status, got)
		}
	}

	e := testCampaign(9804, modeDirect, 0)
	testing.IssueCoins(bondAddr(e.id), chain.NewCoins(chain.NewCoin("ugnot", 200)))
	e.state.bond = 300
	if !panicsWith(func() { bookSlash(e) }, ErrBooksMismatch) {
		t.Errorf("a bond address holding less than the bond: not ErrBooksMismatch")
	}
	if e.state.bondSlashed {
		t.Errorf("a refused slash marked the bond slashed")
	}
}

// TestCheckNotice: "" clears, except on a delisted campaign; any other notice is
// normalized and holds 1–280 characters (API §2.3, §3.5).
func TestCheckNotice(t *testing.T) {
	c := testCampaign(9805, modeEscrow, 0)
	if got := checkNotice(c, ""); got != "" {
		t.Errorf(`"" on a listed campaign: %q`, got)
	}
	if got := checkNotice(c, "  Unverified\tclaims "); got != "Unverified claims" {
		t.Errorf("normalized: %q", got)
	}
	for name, notice := range map[string]string{
		"blank":    " \t ",
		"too long": strings.Repeat("a", noticeMax+1),
	} {
		if !panicsWith(func() { checkNotice(c, notice) }, ErrNotice) {
			t.Errorf("%s: not ErrNotice", name)
		}
	}
	c.state.listed = false
	if !panicsWith(func() { checkNotice(c, "") }, ErrNotice) {
		t.Errorf(`"" on a delisted campaign: not ErrNotice`)
	}
	if got := checkNotice(c, "Fraud reported"); got != "Fraud reported" {
		t.Errorf("a delisted campaign's new notice: %q", got)
	}
}

// TestDelist delists as the admin, straight from the test's body: off the active
// indexes, with the notice; then again, which replaces the notice and slashes, moving
// the bond and only the bond to the slashed address (API §3.5, INV-7).
func TestDelist(cur realm, t *testing.T) {
	rb := banker.NewReadonlyBanker()
	c := testCampaign(9806, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	testing.IssueCoins(bondAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 1000+300)))
	c.state.bond = 300
	slashed, key := rb.GetCoin(slashedAddr(), "ugnot"), c.id.Binary()

	testing.SetRealm(testing.NewUserRealm(admin))
	Delist(cross(cur), id, " Under review ", false)
	if s := c.state; s.listed || s.notice != "Under review" || s.bondSlashed || active.Has(key) || activeByCategory.Has(c.category+"/"+key) {
		t.Errorf("delisted: listed %t, notice %q, slashed %t, active %t", s.listed, s.notice, s.bondSlashed, active.Has(key))
	}
	Delist(cross(cur), id, "Fraud reported", true)
	if s := c.state; s.notice != "Fraud reported" || !s.bondSlashed {
		t.Errorf("delisted again: notice %q, slashed %t", s.notice, s.bondSlashed)
	}
	if got := rb.GetCoin(slashedAddr(), "ugnot") - slashed; got != 300 {
		t.Errorf("the slashed address got %d, want the bond, 300", got)
	}
	if got := rb.GetCoin(bondAddr(c.id), "ugnot"); got != 1000 {
		t.Errorf("the bond address holds %d, want the deposit, 1000", got)
	}
}

// TestRelist: back on the lists, and in the active indexes only while still open; the
// notice stays (API §3.5).
func TestRelist(cur realm, t *testing.T) {
	open := testCampaign(9807, modeEscrow, 0)
	closed := testCampaign(9808, modeEscrow, 0)
	closed.state.status, closed.state.closedAt = statusClosed, now()
	testing.SetRealm(testing.NewUserRealm(admin))
	for _, c := range []*campaign{open, closed} {
		id, unstore := storeCampaign(c)
		Delist(cross(cur), id, "Under review", false)
		Relist(cross(cur), id)
		key := c.id.Binary()
		if !c.state.listed || c.state.notice != "Under review" || active.Has(key) != (c == open) || activeByCategory.Has(c.category+"/"+key) != (c == open) {
			t.Errorf("%s, relisted: listed %t, notice %q, active %t", c.state.status, c.state.listed, c.state.notice, active.Has(key))
		}
		unstore()
	}
}

// TestSetNotice: a notice without delisting, normalized, then cleared (API §3.5).
func TestSetNotice(cur realm, t *testing.T) {
	c := testCampaign(9809, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	testing.SetRealm(testing.NewUserRealm(admin))
	SetNotice(cross(cur), id, " Unverified\tclaims ")
	if c.state.notice != "Unverified claims" || !c.state.listed || !active.Has(c.id.Binary()) {
		t.Errorf("noticed: %q, listed %t", c.state.notice, c.state.listed)
	}
	SetNotice(cross(cur), id, "")
	if c.state.notice != "" {
		t.Errorf("cleared: %q", c.state.notice)
	}
}

// TestHideMessage: the view blanks the message and keeps the receipt — its donor, its
// amount; the stored text stays (API §3.5).
func TestHideMessage(cur realm, t *testing.T) {
	c := testCampaign(9810, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	donor := testutils.TestAddress("donor")
	c.receipts.Set(seqid.ID(1).Binary(), &receipt{seq: 1, donor: donor, amount: 500, message: "Courage"})
	testing.SetRealm(testing.NewUserRealm(admin))
	HideMessage(cross(cur), id, 1)
	if v := GetReceipt(id, 1); v.Message != "" || !v.MessageHidden || v.Amount != 500 || v.Donor != donor {
		t.Errorf("hidden: %v", v)
	}
	if r := receiptOf(c, 1); r.message != "Courage" {
		t.Errorf("the stored text: %q", r.message)
	}
}

package bolo

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"math"
)

// Who hid a campaign's photo: ImageHidden's by (API §6).
const (
	hiderOrganizer = "organizer"
	hiderModerator = "moderator"
)

// PostBond adds what you send to campaign id's bond: a stake its organizer may post,
// lost if Bolo's moderator delists the campaign for fraud. It is not a guarantee. The
// organizer only, while the campaign is open.
//
// It adds the envelope to the campaign's bond (API §3.1): its organizer only, by a
// direct transaction, while the campaign is open, its bond unslashed and Bolo not
// paused. The bond only grows, and the coins go on to the bond address: the
// realm keeps nothing (INV-3).
func PostBond(cur realm, id string) {
	assertCurrent(cur)
	if !cur.Previous().IsUserCall() {
		panic(ErrNotUserCall)
	}
	runtime.AssertOriginCall()
	c := campaignOf(id)
	recordDeadline(cur, c)
	if cur.Previous().Address() != c.organizer {
		panic(ErrNotOrganizer)
	}
	amount := envelopeUgnot()
	checkBond(c, amount)
	c.state.bond += amount
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(realmAddr(), bondAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", amount)))
	chain.Emit(evBondPosted, "id", idString(c.id), "amount", itoa(amount), "bond", itoa(c.state.bond))
}

// checkBond refuses amount as more bond for c (API §3.1), in this order: nothing
// sent, a campaign that isn't open, a slashed bond, a paused Bolo, and a bond that
// would pass int64.
func checkBond(c *campaign, amount int64) {
	if amount <= 0 {
		panic(ErrBadAmount)
	}
	assertOpen(c)
	if c.state.bondSlashed {
		panic(ErrBondSlashed)
	}
	if paused {
		panic(ErrPaused)
	}
	if amount > math.MaxInt64-c.state.bond {
		panic(ErrBadAmount)
	}
}

// assertOpen refuses a campaign that isn't open, by its stored status:
// ErrCampaignSettled once settled, ErrCampaignClosed otherwise. A passed deadline
// is recorded before (API §3.1).
func assertOpen(c *campaign) {
	switch c.state.status {
	case statusOpen:
	case statusSettled:
		panic(ErrCampaignSettled)
	default:
		panic(ErrCampaignClosed)
	}
}

// PostUpdate posts an update on campaign id, shown under its story, and returns the
// update's number: its organizer only. body may hold links, never an image.
//
// It appends an update to the campaign (API §3.1): its organizer only, by a direct
// transaction, in every status and while paused. Updates are append-only, and each
// resets the dormancy clock.
func PostUpdate(cur realm, id, body string) string {
	assertCurrent(cur)
	if !cur.Previous().IsUserCall() {
		panic(ErrNotUserCall)
	}
	runtime.AssertOriginCall()
	c := campaignOf(id)
	recordDeadline(cur, c)
	if cur.Previous().Address() != c.organizer {
		panic(ErrNotOrganizer)
	}
	body = checkStory(body, updateMin, updateMax, ErrUpdate)
	s := c.state
	seq := s.updateSeq.Next()
	c.updates.Set(seq.Binary(), &update{seq: uint64(seq), at: now(), body: body})
	s.updateCount++
	s.lastUpdateAt = now()
	chain.Emit(evUpdatePosted, "id", idString(c.id), "seq", idString(seq))
	return idString(seq)
}

// HideImage hides campaign id's photo, for good: its organizer can, and so can Bolo's
// moderator.
//
// Its organizer may, by a direct transaction, and so may the moderator, with the
// master key — a DAO realm, once one holds the role, through C11's realm branch (API
// §3.1, §3.5). The CID stays: it is a fingerprint, and never replaced. Hiding a
// hidden photo, or a campaign with none, changes nothing.
func HideImage(cur realm, id string) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	c := campaignOf(id)
	recordDeadline(cur, c)
	by := hiderOrganizer
	if cur.Previous().Address() != c.organizer { // an organizer is a user: CreateCampaign admits no other
		assertSigner(cur, admin)
		by = hiderModerator
	}
	if c.text.imageCID == "" || c.state.imageHidden {
		return
	}
	c.state.imageHidden = true
	chain.Emit(evImageHidden, "id", idString(c.id), "by", by)
}

