// TestParseGNOT: an amount in GNOT parses only in its one grammar (API §5).
func TestParseGNOT(t *testing.T) {
	for s, want := range map[string]int64{"1": 1_000_000, "7.5": 7_500_000, "7%2C5": 7_500_000, "0.000001": 1, "0.5": 500_000, "999999999999": 999_999_999_999_000_000, "10.25": 10_250_000,
		"+7.5+": 7_500_000, "++7.5": 7_500_000, "1%2C00": 1_000_000, "1%2C0000": 1_000_000, "1.000": 1_000_000} {
		if got, ok := parseGNOT(s); !ok || got != want {
			t.Errorf("parseGNOT(%q) = %d, %t; want %d", s, got, ok, want)
		}
	}
	for _, s := range []string{"", ".5", "1.", "01", "00.5", "-1", "1e3", "1.1234567", "1,5", "7%2c5", "1 ", " 1", "1..5", "7.5.1", "1234567890123", "%2C5", "1%2C",
		"1%2C000", "12%2C500", "+", "+-1", "7+5"} {
		if got, ok := parseGNOT(s); ok {
			t.Errorf("parseGNOT(%q) accepted: %d", s, got)
		}
	}
}

// TestRenderGive: another amount's page asks the amount in gnoweb's form and answers
// one Donate would take with its one-click link; any other gets the form again with
// what the campaign can take, echoing nothing; a campaign that takes no gift says so
// (API §5).
func TestRenderGive(t *testing.T) {
	c := testCampaign(9976, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	saved := escrowCap
	defer func() { escrowCap, paused = saved, false }()
	escrowCap = 30_000_000
	c.state.raised = 12_000_000 // 18 GNOT of room
	page := func(q string) string { return Render("c/" + id + "/give" + q) }
	form := "\n<gno-form path=\"c/" + id + "/give\">\n  <gno-input name=\"amount\" placeholder=\"7.5\" />\n</gno-form>\n"
	if p := page(""); !strings.Contains(p, form) || !strings.Contains(p, "Any amount from 1 GNOT to 18 GNOT, in GNOT.") || strings.Contains(p, "isn't") {
		t.Errorf("the page for another amount:\n%s", p)
	}
	link := "**[Give 7.5 GNOT](/r/g12yg9nh4ncma44emgm8msxe8aavzywt0p95tanv/bolo/v0$help&func=Donate&.send=7500000ugnot&anonymous=false&id=" + id + "&message=&tip=0)**"
	for _, q := range []string{"?amount=7.5", "?amount=7%2C5"} {
		if p := page(q); !strings.Contains(p, link) || strings.Contains(p, "<gno-form") {
			t.Errorf("%s: no link for 7.5 GNOT, or the form again:\n%s", q, p)
		}
	}
	if p := page("?amount=18"); !strings.Contains(p, "&.send=18000000ugnot&") {
		t.Errorf("the whole room refused:\n%s", p)
	}
	for _, bad := range []string{"0.5", "18.000001", "50", "zz9", "7.5.1", "%3Cb%3Eecho", "1234567890123"} {
		p := page("?amount=" + bad)
		if !strings.Contains(p, "That isn't an amount this campaign can take.") || !strings.Contains(p, form) || strings.Contains(p, "func=Donate") {
			t.Errorf("?amount=%s: a link, or no form and line saying why:\n%s", bad, p)
		}
		if strings.Contains(p, bad) {
			t.Errorf("?amount=%s: the page echoes it:\n%s", bad, p)
		}
	}
	if p := page("?amount=1"); !strings.Contains(p, "&.send=1000000ugnot&") {
		t.Errorf("exactly the smallest gift refused:\n%s", p)
	}
	escrowCap = 0
	if p := page(""); !strings.Contains(p, "Any amount from 1 GNOT, in GNOT.") {
		t.Errorf("no cap, yet a most said:\n%s", p)
	}
	// No link while Bolo is paused, the campaign is hidden or closed, or the cap leaves
	// less room than the smallest gift: the page says so, and links back.
	none := func(why string) {
		if p := page("?amount=1"); strings.Contains(p, "func=Donate") || strings.Contains(p, "<gno-form") || !strings.Contains(p, "Bolo offers no gift link for this campaign now: its page says why.") {
			t.Errorf("%s: a link, or the form:\n%s", why, p)
		}
	}
	paused = true
	none("paused")
	paused = false
	c.state.listed = false
	none("hidden from listings")
	c.state.listed = true
	escrowCap = 12_500_000 // half a GNOT of room
	none("no room")
	escrowCap = 0
	c.state.status = statusClosed
	none("closed")
}

// TestRenderMoney: where the money is comes from the books — the escrow's coins sent
// outside Bolo said apart — and in direct mode all went straight through, with no money
// out on its receipt; the bond reads as at stake, its hold over, or slashed.
func TestRenderMoney(t *testing.T) {
	c := testCampaign(9977, modeEscrow, 0)
	id, unstore := storeCampaign(c)
	defer unstore()
	donor := testutils.TestAddress("moneydonor")
	giveTo(c, 1, donor, 40_000_000)
	defer byDonor.Remove(donor.String() + "/" + c.id.Binary())
	c.state.withdrawn, c.state.refunded, c.state.everWithdrawn = 20_000_000, 2_000_000, true
	testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 27_000_000))) // 18 held, and 9 sent outside Bolo
	page := Render("c/" + id)
	for _, want := range []string{"| Given: 1 gift from 1 donor | 40 |\n", "| Refunded to donors | 2 |\n", "| **Raised**, net of refunds | **38** |\n",
		"| Withdrawn by the beneficiary | 20 |\n", "| Held in escrow | 18 |\n", "its bank balance is the 18 GNOT held, plus 9 GNOT sent there outside Bolo"} {
		if !strings.Contains(page, want) {
			t.Errorf("missing %q:\n%s", want, page)
		}
	}
	c.state.bond = 5_000_000
	if p := Render("c/" + id); !strings.Contains(p, "; a 5 GNOT bond the organizer staked, lost if the campaign is delisted for fraud — not a guarantee\n") {
		t.Errorf("a bond at stake:\n%s", p)
	}
	c.state.status, c.state.closedAt, c.state.closeReason = statusClosed, now()-c.params.BondHold, reasonOrganizer
	if p := Render("c/" + id); !strings.Contains(p, "; a 5 GNOT bond the organizer staked, whose hold ended "+when(now())+": no longer at stake, it goes back to the organizer\n") {
		t.Errorf("a bond whose hold ended:\n%s", p)
	}
	c.state.bondSlashed = true
	if p := Render("c/" + id); !strings.Contains(p, "; a 5 GNOT bond, slashed\n") {
		t.Errorf("a slashed bond:\n%s", p)
	}

	d := testCampaign(9978, modeDirect, 0)
	did, undirect := storeCampaign(d)
	defer undirect()
	giveTo(d, 1, donor, 15_000_000)
	defer byDonor.Remove(donor.String() + "/" + d.id.Binary())
	if p := Render("c/" + did); !strings.Contains(p, "| Given: 1 gift from 1 donor | 15 |\n| Sent straight to the beneficiary | 15 |\n\n") || strings.Contains(p, "Held in escrow") {
		t.Errorf("a direct campaign's money:\n%s", p)
	}
	if r := Render("c/" + did + "/r/1"); strings.Contains(r, "/ledger)") || !strings.Contains(r, "Every gift went straight to the beneficiary, `"+d.beneficiary.String()+"`, in the same transaction.") {
		t.Errorf("a direct receipt:\n%s", r)
	}
}

package bolo

import "gno.land/p/nt/avl/v0"

// Phase 0's values (API §2.2): placeholders for the deposit, the minimum donation and
// the escrow cap, whose launch values API §2.2 proposes, and the three durations it
// proposes. All are settled before Phase 1 (README), and only the admin changes them
// afterwards.
const (
	launchDeposit     int64 = 1_000_000 // ugnot
	launchDormancy    int64 = 90 * secondsPerDay
	launchExitDelay   int64 = 60 * secondsPerDay
	launchBondHold    int64 = 30 * secondsPerDay
	launchMinDonation int64 = 1_000_000     // ugnot, a placeholder
	launchEscrowCap   int64 = 1_000_000_000 // ugnot (1,000 GNOT), a placeholder

	// maxCategories keeps the list GetSettings returns to one bounded read (INV-9).
	maxCategories = 50
)

// The admin and the settings only it changes (API §2.2, §3.6). Package state, all
// unexported (C6).
var (
	admin        address = adminAddr // a realm once a DAO accepts the role (ADR D11)
	pendingAdmin address             // the proposed admin until it accepts; "" for none

	params = Params{ // for campaigns created from now on (INV-5)
		CreationDeposit: launchDeposit,
		DormancyPeriod:  launchDormancy,
		ExitDelay:       launchExitDelay,
		BondHold:        launchBondHold,
	}

	presets              = [4]int64{5_000_000, 10_000_000, 20_000_000, 50_000_000}
	minDonation          = launchMinDonation
	escrowCap            = launchEscrowCap // 0: no cap
	tipRecipient address = adminAddr
	paused       bool
	sunset       bool

	// The categories: a tree to look one up, and the codes in the order they were
	// added, for GetSettings. init fills the tree from the launch set (API §2.1).
	categories    avl.Tree // code → true
	categoryOrder = []string{
		"medical", "emergency", "disaster", "humanitarian", "water", "food",
		"education", "orphans", "animals", "funeral", "worship", "community",
		"sport", "celebration", "personal", "other",
	}
)

// SettingsView is the live settings (API §2.4): a copy, holding nothing of the
// realm's state.
type SettingsView struct {
	Version          string // "v0"
	Presets          [4]int64
	MaxEscrowBalance int64 // 0 = no cap
	Categories       []string
	TipRecipient     address
	MinDonation      int64
	Paused, Sunset   bool
}

// GetParams returns the Params a campaign created now would get (API §4).
func GetParams() Params { return params }

// GetSettings returns the live settings (API §4).
func GetSettings() SettingsView {
	return SettingsView{
		Version:          "v0",
		Presets:          presets,
		MaxEscrowBalance: escrowCap,
		Categories:       append([]string(nil), categoryOrder...),
		TipRecipient:     tipRecipient,
		MinDonation:      minDonation,
		Paused:           paused,
		Sunset:           sunset,
	}
}

// GetAdmin returns the admin and the proposed admin, "" when there is none (API §4).
func GetAdmin() (address, address) { return admin, pendingAdmin }

package bolo

import (
	"chain"
	"chain/banker"
	"math"
	"strconv"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
)

// The helpers' tests come first: a write's test that panics through a crossing call
// ends the package's unit tests.

func TestExitClaim(t *testing.T) {
	for _, k := range []struct{ left, pool, base, want int64 }{
		{100, 150, 300, 50},
		{1, 1, 3, 0}, // rounding down: dust stays in the escrow
		{2, 1, 3, 0},
		{3, math.MaxInt64, 7, 3952873730080618203},
		{math.MaxInt64, math.MaxInt64, math.MaxInt64, math.MaxInt64},
		{math.MaxInt64 / 2, math.MaxInt64 - 1, math.MaxInt64, 4611686018427387902},
		{1_000_000_000_000_000, 1_000_000_000_000_000, 3_000_000_000_000_007, 333333333333332},
		{123456789, 987654321987, 999999999999, 121932631},
		{5, 0, 9, 0},
	} {
		if got := exitClaim(k.left, k.pool, k.base); got != k.want {
			t.Errorf("exitClaim(%d, %d, %d) = %d, want %d", k.left, k.pool, k.base, got, k.want)
		}
	}
	// Neither of Div64's own panics, keyless, is ever reached.
	for name, k := range map[string]struct{ left, pool, base int64 }{
		"a base of 0":            {0, 10, 0},
		"a left above the base":  {11, 10, 10},
		"a negative pool":        {1, -1, 10},
		"a negative base":        {1, 10, -1},
		"past 64 bits otherwise": {math.MaxInt64, math.MaxInt64, math.MaxInt64 - 1},
	} {
		if !panicsWith(func() { exitClaim(k.left, k.pool, k.base) }, ErrBooksMismatch) {
			t.Errorf("%s: not ErrBooksMismatch", name)
		}
	}
}

// exitCampaign is an escrow campaign whose exit window is open: ada, bo and cy gave
// amounts, then withdrawn was taken, and it closed ExitDelay ago. Its escrow holds the
// tracked rest.
func exitCampaign(id seqid.ID, withdrawn int64, amounts ...int64) (*campaign, []address) {
	c := testCampaign(id, modeEscrow, 0)
	donors := []address{testutils.TestAddress("ada"), testutils.TestAddress("bo"), testutils.TestAddress("cy")}
	for i, amount := range amounts {
		c.contributions.Set(donors[i].String(), &contribution{amount: amount})
		c.state.raised += amount
		c.state.donorCount++
	}
	s := c.state
	s.withdrawn, s.everWithdrawn = withdrawn, true
	s.status, s.closedAt = statusClosed, now()-c.params.ExitDelay
	testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", s.raised-withdrawn)))
	return c, donors
}

// TestExitRefunds: the first claim freezes the pool and the base, each donor claims
// once, pro-rata, and the claims never add up to more than the pool (INV-17). The pool
// is the tracked balance: coins sent outside Bolo aren't the donors'. The first model
// is the reviewer's: three gifts of 100, 150 withdrawn, 50 each — where a claim
// repeated against a recomputed pool once drained about 100.
func TestExitRefunds(t *testing.T) {
	for i, k := range []struct {
		withdrawn       int64
		amounts, claims []int64
	}{
		{150, []int64{100, 100, 100}, []int64{50, 50, 50}},
		{300, []int64{100, 200, 300}, []int64{50, 100, 150}},
		{100, []int64{100, 100, 101}, []int64{66, 66, 67}}, // rounded down: 2 stay in the escrow
	} {
		c, donors := exitCampaign(seqid.ID(9501+100*i), k.withdrawn, k.amounts...)
		testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 7))) // sent outside Bolo
		id, unstore := storeCampaign(c)
		pool, base := c.state.raised-k.withdrawn, c.state.raised
		checkBooks(t, c)
		if v := GetContribution(id, donors[1]); v.Window != windowExit || v.RefundableNow != k.claims[1] {
			t.Errorf("model %d, bo before any claim: %v", i, v)
		}
		var paid int64
		for j, want := range k.claims {
			r := bookRefund(c, donors[j])
			checkBooks(t, c)
			if r.amount != want || r.kind != windowExit {
				t.Errorf("model %d, claim %d = %v, want %d", i, j, *r, want)
			}
			paid += r.amount
			// The snapshot is the first claim's, never recomputed (INV-17).
			if s := c.state; !s.exitFrozen || s.exitPool != pool || s.exitBase != base {
				t.Errorf("model %d, after claim %d: frozen %t, pool %d, base %d", i, j, s.exitFrozen, s.exitPool, s.exitBase)
			}
			if !panicsWith(func() { bookRefund(c, donors[j]) }, ErrRefundWindowClosed) {
				t.Errorf("model %d, a second claim by donor %d: not ErrRefundWindowClosed", i, j)
			}
			if v := GetContribution(id, donors[j]); v.Window != "" || v.RefundableNow != 0 || !v.ExitClaimed {
				t.Errorf("model %d, donor %d after their claim: %v", i, j, v)
			}
		}
		if paid > pool {
			t.Errorf("model %d: the claims add up to %d, past the pool %d", i, paid, pool)
		}
		unstore()
	}
}

// TestExitClaimCap: a claim above the tracked balance is ErrBooksMismatch, whatever
// the snapshot says (INV-17).
func TestExitClaimCap(t *testing.T) {
	c, donors := exitCampaign(9520, 150, 100, 100, 100)
	s := c.state
	s.exitFrozen, s.exitPool, s.exitBase = true, 300, 100 // ada's claim: 300, the tracked balance 150
	if !panicsWith(func() { bookRefund(c, donors[0]) }, ErrBooksMismatch) {
		t.Errorf("a claim above the tracked balance: not ErrBooksMismatch")
	}
}

// TestExitBase: the base is what is left of every record when the first claim comes,
// Raised − Refunded: an open-window refund before the withdrawal is taken out of it.
func TestExitBase(t *testing.T) {
	c := testCampaign(9502, modeEscrow, 0)
	ada, bo, cy := testutils.TestAddress("ada"), testutils.TestAddress("bo"), testutils.TestAddress("cy")
	c.contributions.Set(ada.String(), &contribution{amount: 400})
	c.contributions.Set(bo.String(), &contribution{amount: 200})
	c.contributions.Set(cy.String(), &contribution{amount: 300, refunded: 300}) // all back, in the open window
	s := c.state
	s.raised, s.refunded, s.withdrawn, s.everWithdrawn = 900, 300, 300, true
	s.status, s.closedAt = statusClosed, now()-c.params.ExitDelay
	testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 300)))
	checkBooks(t, c)
	// Tracked 300, base 600 — ada's 400 and bo's 200: ada claims 400 × 300 / 600.
	if r := bookRefund(c, ada); r.amount != 200 || s.exitBase != 600 || s.exitPool != 300 {
		t.Errorf("ada's claim %d; base %d, pool %d", r.amount, s.exitBase, s.exitPool)
	}
	checkBooks(t, c)
}

// TestExitUneven: forty donors with uneven gifts, some refunded in the open window,
// then a withdrawal, more gifts from half of them and others, and every donor's claim
// in a scrambled order. Each claim is paid from the tracked balance, the claims never
// pass the pool, and what is left is rounding dust, under one ugnot a claim (INV-17).
func TestExitUneven(t *testing.T) {
	c := testCampaign(9519, modeEscrow, 0)
	x := int64(12345)
	next := func() int64 { // a fixed sequence of amounts from 1 to about a million
		x = (x*1103515245 + 12345) % 2147483648
		return x%1_000_003 + 1
	}
	donors := make([]address, 40)
	for i := range donors {
		donors[i] = testutils.TestAddress("donor" + strconv.Itoa(i))
	}
	s := c.state
	for i := 0; i < 20; i++ {
		if i%7 == 3 { // refunded in full in the open window: the coins went back
			a := next()
			c.contributions.Set(donors[i].String(), &contribution{amount: a, refunded: a})
			s.raised, s.refunded, s.donorCount = s.raised+a, s.refunded+a, s.donorCount+1
			continue
		}
		fund(c, donors[i], next())
	}
	bookWithdrawal(c)
	for i := 10; i < 40; i++ {
		fund(c, donors[i], next())
	}
	s.status, s.closedAt = statusClosed, now()-c.params.ExitDelay
	checkBooks(t, c)
	pool := trackedBalance(c)
	var paid, claims int64
	for i := 0; i < 40; i++ {
		d := donors[i*17%40] // every donor once: 17 and 40 share no factor
		if k := contributionOf(c, d); k.amount == k.refunded {
			continue
		}
		left := trackedBalance(c)
		r := bookRefund(c, d)
		checkBooks(t, c)
		if r.amount > left || r.amount <= 0 {
			t.Errorf("a claim of %d against a tracked %d", r.amount, left)
		}
		paid += r.amount
		claims++
	}
	if paid > pool || pool-paid >= claims || claims != 39 { // all but donor 3: refunded in full, never gave again
		t.Errorf("%d claims paid %d of a pool %d", claims, paid, pool)
	}
}

// TestExitWindow: the exit window needs a withdrawal, a close, ExitDelay passed and a
// tracked balance; a claim that rounds to 0 uses nothing.
func TestExitWindow(t *testing.T) {
	c, donors := exitCampaign(9503, 300, 100, 200, 300)
	c.state.closedAt = now() - c.params.ExitDelay + 1
	if !panicsWith(func() { checkRefund(c, donors[0]) }, ErrRefundWindowClosed) {
		t.Errorf("a second before the exit window: not ErrRefundWindowClosed")
	}
	c.state.closedAt = now() - c.params.ExitDelay
	checkRefund(c, donors[0])
	c.state.status = statusSettled
	checkRefund(c, donors[0]) // settlement closes no window (INV-16)
	c.state.status = statusOpen
	if !panicsWith(func() { checkRefund(c, donors[0]) }, ErrRefundWindowClosed) {
		t.Errorf("open: not ErrRefundWindowClosed")
	}
	c.state.status = statusClosed
	c.state.withdrawn = 600 // nothing tracked left
	if !panicsWith(func() { checkRefund(c, donors[0]) }, ErrRefundWindowClosed) {
		t.Errorf("no tracked balance: not ErrRefundWindowClosed")
	}

	// Dust: a gift of 1 against a pool far smaller than the base claims 0.
	d := testCampaign(9504, modeEscrow, 0)
	tiny, big := testutils.TestAddress("tiny"), testutils.TestAddress("big")
	d.contributions.Set(tiny.String(), &contribution{amount: 1})
	d.contributions.Set(big.String(), &contribution{amount: 1000})
	d.state.raised, d.state.withdrawn, d.state.everWithdrawn = 1001, 1000, true
	d.state.status, d.state.closedAt = statusClosed, now()-d.params.ExitDelay
	if !panicsWith(func() { checkRefund(d, tiny) }, ErrNothingToRefund) {
		t.Errorf("a claim of 0: not ErrNothingToRefund")
	}
	if contributionOf(d, tiny).exitClaimed {
		t.Errorf("a claim of 0 used the claim")
	}
	dustID, unstoreDust := storeCampaign(d)
	if v := GetContribution(dustID, tiny); v.Window != "" || v.RefundableNow != 0 {
		t.Errorf("a claim of 0 shows a window Refund refuses: %v", v)
	}
	unstoreDust()

	// GetContribution counts a passed deadline as recorded: the stored status is open.
	e := testCampaign(9505, modeEscrow, now()-61*secondsPerDay)
	e.contributions.Set(tiny.String(), &contribution{amount: 100})
	e.contributions.Set(big.String(), &contribution{amount: 100})
	e.state.raised, e.state.withdrawn, e.state.everWithdrawn = 200, 100, true
	id, unstore := storeCampaign(e)
	defer unstore()
	if v := GetContribution(id, tiny); v.Window != windowExit || v.RefundableNow != 50 {
		t.Errorf("past an unrecorded deadline and its exit delay: %v", v)
	}
}

func TestCheckFinalizable(t *testing.T) {
	c := testCampaign(9506, modeEscrow, 0)
	if !panicsWith(func() { checkFinalizable(c) }, ErrNotFinalizable) {
		t.Errorf("open: not ErrNotFinalizable")
	}
	c.state.status, c.state.closedAt = statusClosed, now()
	checkFinalizable(c) // nothing tracked
	c.state.raised = 10
	if !panicsWith(func() { checkFinalizable(c) }, ErrNotFinalizable) {
		t.Errorf("a tracked balance before the exit window: not ErrNotFinalizable")
	}
	c.state.closedAt = now() - c.params.ExitDelay
	checkFinalizable(c) // the exit window is open
	d := testCampaign(9507, modeDirect, 0)
	d.state.status, d.state.closedAt = statusClosed, now()
	checkFinalizable(d) // direct: at once
}

// TestFinalizeBooks: the first call settles; untracked coins go to the beneficiary,
// the tracked balance never; the bond address's coins to the organizer, but a bond on
// hold; the bond once its hold ends, unless slashed; later calls forward what arrives.
func TestFinalizeBooks(t *testing.T) {
	c := testCampaign(9508, modeEscrow, 0)
	fund(c, testutils.TestAddress("donor"), 500) // tracked, the donors'
	testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 70)))
	testing.IssueCoins(bondAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 1000+300)))
	c.state.bond = 300
	c.state.status, c.state.closedAt = statusClosed, now()-c.params.ExitDelay
	f := bookFinalize(c)
	if !f.settled || c.state.status != statusSettled || f.toBeneficiary != 70 || f.toOrganizer != 1300 || f.released != 300 || !c.state.bondReleased {
		// ExitDelay (60 days) is past BondHold (30): the bond goes too.
		t.Errorf("first call: %v", f)
	}

	// On hold: a campaign closed now keeps its bond at the bond address.
	d := testCampaign(9509, modeDirect, 0)
	testing.IssueCoins(bondAddr(d.id), chain.NewCoins(chain.NewCoin("ugnot", 1000+300)))
	d.state.bond = 300
	d.state.status, d.state.closedAt = statusClosed, now()
	f = bookFinalize(d)
	if !f.settled || f.toOrganizer != 1000 || f.released != 0 || d.state.bondReleased {
		t.Errorf("bond on hold: %v", f)
	}
	// The coins don't move here; a later call, before the hold ends, has the same
	// 1000 to forward and still holds the bond, without settling again.
	if f = bookFinalize(d); f.settled || f.toOrganizer != 1000 || f.released != 0 {
		t.Errorf("a second call on hold: %v", f)
	}
	// A slashed bond is never released: the slash took it, and the deposit is left.
	e := testCampaign(9518, modeDirect, 0)
	testing.IssueCoins(bondAddr(e.id), chain.NewCoins(chain.NewCoin("ugnot", 1000)))
	e.state.bond, e.state.bondSlashed = 300, true
	e.state.status, e.state.closedAt = statusClosed, now()-e.params.BondHold
	if f = bookFinalize(e); f.released != 0 || e.state.bondReleased || f.toOrganizer != 1000 {
		t.Errorf("slashed: %v", f)
	}
	// Within the hold too: the slash took the bond, so the deposit goes at once.
	s := testCampaign(9530, modeDirect, 0)
	testing.IssueCoins(bondAddr(s.id), chain.NewCoins(chain.NewCoin("ugnot", 1000)))
	s.state.bond, s.state.bondSlashed = 300, true
	s.state.status, s.state.closedAt = statusClosed, now()
	if f = bookFinalize(s); !f.settled || f.released != 0 || f.toOrganizer != 1000 {
		t.Errorf("slashed, within the hold: %v", f)
	}

	// A bond address holding less than the bond on hold stops it (INV-7).
	h := testCampaign(9521, modeDirect, 0)
	testing.IssueCoins(bondAddr(h.id), chain.NewCoins(chain.NewCoin("ugnot", 200)))
	h.state.bond = 300
	h.state.status, h.state.closedAt = statusClosed, now()
	if !panicsWith(func() { bookFinalize(h) }, ErrBooksMismatch) {
		t.Errorf("a bond above the bond address's coins: not ErrBooksMismatch")
	}

	// Books above the bank stop it (INV-1).
	g := testCampaign(9510, modeEscrow, 0)
	g.state.raised = 5
	g.state.status, g.state.closedAt = statusClosed, now()-g.params.ExitDelay
	if !panicsWith(func() { bookFinalize(g) }, ErrBooksMismatch) {
		t.Errorf("books above the bank: not ErrBooksMismatch")
	}
}

func TestCanFinalize(t *testing.T) {
	open := testCampaign(9511, modeEscrow, 0)
	waiting := testCampaign(9512, modeEscrow, 0)
	fund(waiting, testutils.TestAddress("donor"), 10)
	waiting.state.status, waiting.state.closedAt = statusClosed, now()
	ready := testCampaign(9513, modeDirect, 0)
	ready.state.status, ready.state.closedAt = statusClosed, now()
	passed := testCampaign(9514, modeDirect, now()-1) // past its deadline, unrecorded
	exit := testCampaign(9522, modeEscrow, 0)
	fund(exit, testutils.TestAddress("donor"), 10)
	exit.state.status, exit.state.closedAt = statusClosed, now()-exit.params.ExitDelay // its exit window opens now
	settled := testCampaign(9515, modeDirect, 0)
	settled.state.status, settled.state.closedAt = statusSettled, now()
	stray := testCampaign(9516, modeDirect, 0)
	stray.state.status, stray.state.closedAt = statusSettled, now()
	testing.IssueCoins(escrowAddr(stray.id), chain.NewCoins(chain.NewCoin("ugnot", 3)))
	for _, k := range []struct {
		name string
		c    *campaign
		ok   bool
		why  string
	}{
		{"open", open, false, statusOpen},
		{"waiting for the exit window", waiting, false, "not_yet"},
		{"closed, direct", ready, true, "settle"},
		{"past an unrecorded deadline", passed, true, "settle"},
		{"at the exit window", exit, true, "settle"},
		{"settled, nothing to move", settled, false, statusSettled},
		{"settled, coins arrived", stray, true, "forward"},
	} {
		id, unstore := storeCampaign(k.c)
		ok, why := CanFinalize(id)
		unstore()
		if ok != k.ok || why != k.why {
			t.Errorf("%s: CanFinalize = %t, %q, want %t, %q", k.name, ok, why, k.ok, k.why)
		}
	}
}

// TestFinalize settles as anyone, straight from the test's body, and moves the coins
// bookFinalize names: the untracked to the beneficiary, the deposit to the organizer,
// the tracked balance nowhere (INV-16), which a donor still claims after (API §3.4).
func TestFinalize(cur realm, t *testing.T) {
	rb := banker.NewReadonlyBanker()
	c, donors := exitCampaign(9517, 300, 100, 200, 300)
	id, unstore := storeCampaign(c)
	defer unstore()
	testing.IssueCoins(escrowAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 40))) // sent outside Bolo
	testing.IssueCoins(bondAddr(c.id), chain.NewCoins(chain.NewCoin("ugnot", 1000))) // the deposit
	checkBooks(t, c)
	beneficiary, organizer := rb.GetCoin(c.beneficiary, "ugnot"), rb.GetCoin(c.organizer, "ugnot")
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("passerby")))
	Finalize(cross(cur), id)
	checkBooks(t, c)
	if got := rb.GetCoin(c.beneficiary, "ugnot") - beneficiary; got != 40 {
		t.Errorf("the beneficiary got %d, want the untracked 40", got)
	}
	if got := rb.GetCoin(c.organizer, "ugnot") - organizer; got != 1000 {
		t.Errorf("the organizer got %d, want the deposit 1000", got)
	}
	if got := rb.GetCoin(escrowAddr(c.id), "ugnot"); got != 300 || c.state.status != statusSettled {
		t.Errorf("the escrow holds %d; status %s", got, c.state.status)
	}
	// Claims still paid after settlement (INV-16).
	testing.SetRealm(testing.NewUserRealm(donors[2]))
	if got := Refund(cross(cur), id); got != 150 {
		t.Errorf("cy's exit claim after settlement = %d, want 150", got)
	}
	checkBooks(t, c)
}

package bolo

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// Params are the settings snapshotted into each campaign when it is created
// (API §2.2): its deposit and its timers never change afterwards (INV-5).
// Durations are in seconds.
type Params struct {
	CreationDeposit int64
	DormancyPeriod  int64
	ExitDelay       int64
	BondHold        int64
}

// Custody modes, statuses and close reasons (API §2.1).
const (
	modeDirect = "direct"
	modeEscrow = "escrow"

	statusOpen    = "open"
	statusClosed  = "closed"
	statusSettled = "settled"

	reasonOrganizer = "organizer"
	reasonDeadline  = "deadline"
	reasonDormant   = "dormant"
)

// campaign holds what never changes once a campaign is created (INV-10), and
// points to what does. Gno re-saves a changed object and every object that owns
// it, up to the first with two owners, so each donation re-saves this object with
// its hot state and its trees: it holds only small fields, and the organizer's
// text lives in its own object, written once (API §2.5).
type campaign struct {
	id          seqid.ID
	category    string
	organizer   address
	beneficiary address
	mode        string // modeDirect or modeEscrow
	goal        int64  // ugnot; 0: no goal
	deadline    int64  // Unix seconds; 0: none
	createdAt   int64
	params      Params

	text  *campaignText  // written once; read by views and Render
	state *campaignState // counters, timers and flags

	// One object each, keyed by donor address or by seqid.Binary(): a donation
	// writes O(log n) small nodes, not the campaign's history.
	contributions *avl.Tree // address → *contribution
	receipts      *avl.Tree // seq → *receipt
	withdrawals   *avl.Tree // seq → *withdrawal
	refunds       *avl.Tree // seq → *refund
	updates       *avl.Tree // seq → *update
}

// campaignText is what the organizer wrote, which never changes (INV-10): written
// once, off the path every donation re-saves.
type campaignText struct {
	title       string
	description string
	imageCID    string
	imageAlt    string
}

const recentSize = 20

// campaignState is a campaign's hot object: small, rewritten on every donation.
type campaignState struct {
	status      string // as stored; a passed deadline counts as closed before it is recorded
	closeReason string
	closedAt    int64
	listed      bool
	notice      string
	imageHidden bool

	raised    int64 // gross: every donation ever
	refunded  int64
	withdrawn int64 // tracked coins only; untracked ones are counted apart

	donorCount    int
	donationCount int
	refundCount   int
	updateCount   int

	bond         int64
	bondSlashed  bool
	bondReleased bool

	lastDonationAt int64
	lastUpdateAt   int64
	everWithdrawn  bool // ends the open refund window for good

	// The exit window's snapshot, frozen by the first exit claim (API §3.2).
	exitFrozen bool
	exitPool   int64
	exitBase   int64

	// The last donations' sequence numbers, a ring: numbers, not receipts.
	recent     [recentSize]uint64
	recentNext int

	receiptSeq    seqid.ID
	withdrawalSeq seqid.ID
	refundSeq     seqid.ID
	updateSeq     seqid.ID
}

// contribution is one donor's record in one campaign (API §3.2).
type contribution struct {
	amount      int64 // everything given
	refunded    int64 // everything paid back
	exitClaimed bool  // the one exit claim is used (INV-17)
	public      bool  // at least one gift wasn't anonymous
}

// receipt is one donation.
type receipt struct {
	seq           uint64
	donor         address
	anonymous     bool
	amount        int64
	tip           int64
	message       string
	messageHidden bool
	at            int64
	raisedAfter   int64

	refundedBefore int64 // what this donor was refunded on this campaign before this gift
}

// withdrawal is one payout to the beneficiary.
type withdrawal struct {
	seq       uint64
	amount    int64 // tracked coins
	untracked int64 // coins sent to the escrow outside Bolo
	at        int64
	to        address
}

// refund is one payout to a donor.
type refund struct {
	seq    uint64
	amount int64
	at     int64
	donor  address
	kind   string // "open" or "exit"
}

// update is one organizer update: append-only.
type update struct {
	seq  uint64
	at   int64
	body string
}

// Package state, all unexported (API C6).
var (
	nextID    seqid.ID // the last campaign ID given out
	campaigns avl.Tree // seqid.Binary() → *campaign

	// derived holds every escrow and bond address a campaign ever got: none of
	// them may be a beneficiary (API §1).
	derived avl.Tree // address → true

	// The indexes (API §2.5): keys sort newest campaign last.
	active           avl.Tree // seqid.Binary() → true: the open, listed campaigns
	activeByCategory avl.Tree // category + "/" + seqid.Binary() → true: the same
	byOrganizer      avl.Tree // organizer + "/" + seqid.Binary() → true
	byBeneficiary    avl.Tree // beneficiary + "/" + seqid.Binary() → true
	byDonor          avl.Tree // donor + "/" + seqid.Binary() → true: a gift that wasn't anonymous
)

package bolo

// statsState holds Bolo-wide counters (API §2.4), kept as things happen, never by
// walking the campaigns. Gift and refund totals aren't kept: an indexer sums them.
type statsState struct {
	open    int // campaigns whose close isn't recorded yet
	settled int // campaigns settled
}

var stats statsState

// StatsView is what GetStats returns (API §2.4).
type StatsView struct {
	Campaigns, Open, Settled int
}

// GetStats returns Bolo-wide figures (API §4). Open counts a campaign past a deadline
// nobody recorded until someone does (§3.1).
func GetStats() StatsView {
	return StatsView{Campaigns: campaigns.Size(), Open: stats.open, Settled: stats.settled}
}

package bolo

import (
	"strings"
	"unicode"
	"unicode/utf8"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Text limits in characters — Unicode code points — after normalization (API
// §2.3). Every text also has a byte cap of four times its character limit, on
// the argument as sent.
const (
	titleMin, titleMax   = 4, 80
	descriptionMax       = 5000
	messageMax           = 140
	updateMin, updateMax = 1, 2000
	noticeMin, noticeMax = 1, 280
	altMin, altMax       = 1, 250
	cidMaxBytes          = 100
)

// normalize prepares user text for checking and storing (API C7, §2.3). Bidi and
// zero-width characters go first, through the very function sanitize.Block calls
// when it renders, so that no check can be dodged by what rendering removes. Line
// breaks are unified — CR-LF, CR, NEL and the Unicode line and paragraph
// separators all become "\n" — and kept in multiline text; elsewhere they become
// a space. Tabs and the other whitespace controls (a vertical tab, a form feed, the
// information separators) become a space everywhere, so words never join. Then
// every character that only pads a text goes (invisible), and surrounding
// whitespace is trimmed. Stripping more than Block does only makes the checks
// stricter, and the stripped text is what gets stored.
func normalize(s string, multiline bool) string {
	s = sanitize.StripBidiAndZeroWidth(s)
	s = sanitize.NormalizeBreaks(s)
	s = strings.Map(func(r rune) rune {
		switch {
		case r == '\n' || r == '\u0085' || r == '\u2028' || r == '\u2029':
			if multiline {
				return '\n'
			}
			return ' '
		case r == '\t' || r == '\v' || r == '\f' || (r >= '\x1c' && r <= '\x1f'):
			return ' '
		case invisible(r):
			return -1
		}
		return r
	}, s)
	return strings.TrimSpace(s)
}

// invisible reports whether r shows nothing and only pads a text: a control or a
// format character (Unicode Cc, Cf: a word joiner, a soft hyphen), one Unicode
// lists as Other_Default_Ignorable_Code_Point (a Hangul filler, the combining
// grapheme joiner), or a blank symbol (the Braille blank, the musical null
// notehead). A Latin-1 character skips the tables, which are costly and which
// English or French text seldom leaves: of them, only the controls and the soft
// hyphen are invisible (TestLatin1 holds this to the tables). Every control is
// Latin-1.
func invisible(r rune) bool {
	if r <= unicode.MaxLatin1 {
		return r < 0x20 || r >= 0x7f && r <= 0x9f || r == 0xad
	}
	return unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Other_Default_Ignorable_Code_Point, r) ||
		r == '\u2800' || r == '\U0001D159'
}

// checkText checks one text argument and returns it normalized, the form Bolo
// stores (API §2.3): valid UTF-8 and at most four bytes per allowed character as
// sent; then, normalized, at most max characters, of which at least min show on
// their own. It panics with err otherwise.
func checkText(s string, min, max int, multiline bool, err Error) string {
	if !utf8.ValidString(s) || len(s) > 4*max {
		panic(err)
	}
	s = normalize(s, multiline)
	if utf8.RuneCountInString(s) > max || !visible(s, min) {
		panic(err)
	}
	return s
}

// visible reports whether at least min characters of s show on their own —
// letters, digits, punctuation, symbols and spacing marks — counting the spaces
// between two of them. A mark that takes no space (an accent, a variation
// selector) only changes the character before it, a private-use character or a
// code point Unicode hasn't assigned shows nothing a reader can count on, and a
// space shows only between characters that do. They all stay in the text, but
// don't count toward a minimum. Latin-1 skips the tables, as in invisible: there,
// every character shows on its own but the controls, the soft hyphen and the two
// spaces, ' ' and U+00A0. Counting stops once min characters have shown, so a long
// text pays the tables only until then, and a story, whose minimum is 0, never.
func visible(s string, min int) bool {
	n, spaces, shown := 0, 0, false
	for _, r := range s {
		if n >= min {
			break
		}
		switch {
		case r > ' ' && r < 0x7f, r > 0xa0 && r <= unicode.MaxLatin1 && r != 0xad,
			r > unicode.MaxLatin1 && unicode.In(r, unicode.L, unicode.Mc, unicode.N, unicode.P, unicode.S):
			n += 1 + spaces
			spaces, shown = 0, true
		case shown && (r == ' ' || r == 0xa0 || r > unicode.MaxLatin1 && unicode.Is(unicode.Zs, r)):
			spaces++
		}
	}
	return n >= min
}

// checkStory checks a story or an update, the organizer's own text, and returns it
// normalized (API §2.3): the limits of checkText, then no image and no raw HTML,
// judged on the normalized text that sanitize.Block will render.
func checkStory(s string, min, max int, err Error) string {
	s = checkText(s, min, max, true, err)
	checkMarkup(s)
	return s
}

// checkMarkup refuses an image or raw HTML (API §2.3): `![`, or `<` followed by a
// letter, `/`, `!` or `?` — every way CommonMark opens raw HTML. The campaign
// photo is the only image a campaign shows, and `<3` still passes.
func checkMarkup(s string) {
	if strings.Contains(s, "![") {
		panic(ErrMarkup)
	}
	for i := 0; i+1 < len(s); i++ {
		if s[i] != '<' {
			continue
		}
		c := s[i+1]
		if c == '/' || c == '!' || c == '?' || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') {
			panic(ErrMarkup)
		}
	}
}

// checkImage checks a campaign photo's CID and its description (API §2.3, ADR
// D16), and returns both, the description normalized: no photo, no description;
// a photo, a description of 1 to 250 characters.
func checkImage(cid, alt string) (string, string) {
	if cid == "" {
		if alt != "" {
			panic(ErrImage)
		}
		return "", ""
	}
	if !validCID(cid) {
		panic(ErrImage)
	}
	return cid, checkText(alt, altMin, altMax, false, ErrImage)
}

// validCID reports whether s has the shape of an IPFS CID Bolo accepts: v0, "Qm"
// and 44 more base58btc characters; or v1 in lowercase base32, "b" then that
// alphabet; at most 100 bytes. Render writes the CID into `(ipfs://…)` as it is,
// so the character set is the escaping (API §2.3).
func validCID(s string) bool {
	switch {
	case len(s) > cidMaxBytes:
		return false
	case len(s) == 46 && strings.HasPrefix(s, "Qm"):
		return allIn(s, base58btc)
	case len(s) > 1 && s[0] == 'b':
		return allIn(s[1:], base32Lower)
	}
	return false
}

const (
	base58btc   = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
	base32Lower = "abcdefghijklmnopqrstuvwxyz234567"
)

func allIn(s, set string) bool {
	for i := 0; i < len(s); i++ {
		if strings.IndexByte(set, s[i]) < 0 {
			return false
		}
	}
	return true
}

package bolo

import (
	"strings"
	"testing"
	"unicode"
)

func TestNormalize(t *testing.T) {
	for _, c := range []struct {
		in        string
		multiline bool
		want      string
	}{
		{"  Clean water  ", false, "Clean water"},
		{"a\u200bb\u202ec\ufeffd\u2066e", false, "abcde"},
		{"one\r\ntwo\rthree", true, "one\ntwo\nthree"},
		// Every line break is one; outside multiline text, it and a tab become a
		// space, so words never join.
		{"one\r\ntwo\nthree", false, "one two three"},
		{"bell\a and\ttab", false, "bell and tab"},
		{"rub\x7fout", false, "rubout"},
		{"a\vb\fc\x1cd\x1fe", false, "a b c d e"},
		{"a\tb\vc", true, "a b c"},
		{"a\u0085b\u2028c\u2029d", true, "a\nb\nc\nd"},
		{"a\u0085b\u2028c\u2029d", false, "a b c d"},
		{"word\u2060joiner, soft\u00adhyphen", false, "wordjoiner, softhyphen"},
		// Fillers that show nothing go: Hangul fillers, the combining grapheme
		// joiner, the Braille blank. A variation selector stays, for emoji.
		{"a\u3164b\uffa0c\u115fd\u034fe\u2800f\U0001D159g", false, "abcdefg"},
		{"I \u2764\ufe0f you", false, "I \u2764\ufe0f you"},
		{"\n\n story \n\n", true, "story"},
	} {
		if got := normalize(c.in, c.multiline); got != c.want {
			t.Errorf("normalize(%q, %t) = %q, want %q", c.in, c.multiline, got, c.want)
		}
	}
}

// TestLatin1 holds the Latin-1 shortcut of invisible and visible to the Unicode
// tables they read beyond it: invisible is Cc, Cf or Other_Default_Ignorable; a
// character shows on its own (counts alone) if it is L, Mc, N, P or S; a space (Zs)
// counts only between two of those.
func TestLatin1(t *testing.T) {
	for r := rune(0); r <= unicode.MaxLatin1; r++ {
		if want := unicode.In(r, unicode.Cc, unicode.Cf, unicode.Other_Default_Ignorable_Code_Point); invisible(r) != want {
			t.Errorf("invisible(%U) = %t, the tables say %t", r, !want, want)
		}
		shows := unicode.In(r, unicode.L, unicode.Mc, unicode.N, unicode.P, unicode.S)
		if got := visible(string(r), 1); got != shows {
			t.Errorf("visible(%U, 1) = %t, the tables say %t", r, got, shows)
		}
		between := shows || unicode.Is(unicode.Zs, r)
		if got := visible("x"+string(r)+"x", 3); got != between {
			t.Errorf("visible(x %U x, 3) = %t, the tables say %t", r, got, between)
		}
	}
}

// TestVisible checks visible's threshold: at least min, the spaces between two
// shown characters counted, marks and spaces elsewhere not.
func TestVisible(t *testing.T) {
	for _, c := range []struct {
		s    string
		min  int
		want bool
	}{
		{"", 0, true},
		{"", 1, false},
		{"abc", 4, false},
		{"abcd", 4, true},
		{"ab cd", 5, true},
		{"ab  ", 3, false},
		{"a\u0301\u0301\u0301", 2, false},
	} {
		if got := visible(c.s, c.min); got != c.want {
			t.Errorf("visible(%q, %d) = %t, want %t", c.s, c.min, got, c.want)
		}
	}
}

func TestCheckText(t *testing.T) {
	if got := checkText("  Clean water for Ndiaganiao ", titleMin, titleMax, false, ErrTitle); got != "Clean water for Ndiaganiao" {
		t.Errorf("checkText = %q", got)
	}
	// 80 characters of four bytes each: exactly the byte cap.
	if got := checkText(strings.Repeat("💧", 80), titleMin, titleMax, false, ErrTitle); len(got) != 320 {
		t.Errorf("80 four-byte characters: got %d bytes", len(got))
	}
	// Four letters, one with a combining accent: four characters show. So do
	// emoji with a skin tone, flags, CJK, Arabic, a Devanagari word with a spacing
	// vowel sign, and two letters with the spaces between them.
	for _, s := range []string{"Cafe\u0301", "\U0001F44D\U0001F3FD\U0001F44D\U0001F3FD", "\U0001F1F8\U0001F1F3\U0001F1F8\U0001F1F3", "水井项目", "بئر ماء", "कमला", "a  b"} {
		if got := checkText(s, titleMin, titleMax, false, ErrTitle); got != s {
			t.Errorf("checkText(%q) = %q", s, got)
		}
	}
	for name, s := range map[string]string{
		"too short":                 "abc",
		"four spaces":               "    ",
		"four invisible characters": "\u200b\u200b\u200b\u200b",
		"four word joiners":         "\u2060\u2060\u2060\u2060",
		"four soft hyphens":         "\u00ad\u00ad\u00ad\u00ad",
		"four Hangul fillers":       "\u3164\u3164\u3164\u3164",
		"four halfwidth fillers":    "\uffa0\uffa0\uffa0\uffa0",
		"four grapheme joiners":     "\u034f\u034f\u034f\u034f",
		"four Braille blanks":       "\u2800\u2800\u2800\u2800",
		"four variation selectors":  "\ufe0f\ufe0f\ufe0f\ufe0f",
		"one letter, three accents": "a\u0301\u0301\u0301",
		"four null noteheads":       "\U0001D159\U0001D159\U0001D159\U0001D159",
		"four private-use":          "\ue000\ue000\ue000\ue000",
		"four noncharacters":        "\uffff\uffff\uffff\uffff",
		// Spaces count only between shown characters: wrapped in characters
		// that don't count, they would escape the trim and pass as a title.
		"spaces in variation selectors":  "\ufe0f    \ufe0f",
		"spaces in accents":              "\u0301    \u0301",
		"spaces in private-use":          "\ue000    \ue000",
		"spaces in noncharacters":        "\uffff    \uffff",
		"no-break spaces in selectors":   "\U000E0100\u00a0\u00a0\u00a0\u00a0\U000E0100",
		"ideographic spaces":             "\ufe0f\u3000\u3000\u3000\u3000\ufe0f",
		"one letter and trailing spaces": "a\ufe0f   \ufe0f",
		"leading spaces and one letter":  "\ufe0f    a",
		"too long":                       strings.Repeat("a", 81),
		"invalid UTF-8":                  "\xff\xfeabcd",
		// Fits once normalized, but is more than four bytes per allowed character
		// as sent: the byte cap applies to the argument (API §2.3).
		"padded past the byte cap": "abcd" + strings.Repeat("\u200b", 110),
	} {
		if !panicsWith(func() { checkText(s, titleMin, titleMax, false, ErrTitle) }, ErrTitle) {
			t.Errorf("%s: not refused", name)
		}
	}
}

func TestCheckStory(t *testing.T) {
	// Accepted, and stored normalized; a refusal of any kind fails the test.
	for _, c := range []struct{ in, want string }{
		{"We need **1,500 GNOT** for the pump.\n\nSee [the quote](https://example.org/q).", "We need **1,500 GNOT** for the pump.\n\nSee [the quote](https://example.org/q)."},
		{"Thanks <3 to everyone", "Thanks <3 to everyone"},
		{"a < b, and x<5", "a < b, and x<5"},
		{"", ""},
		{" Line one\r\n\r\nline\u2028two\t ", "Line one\n\nline\ntwo"},
	} {
		if got := checkStory(c.in, 0, descriptionMax, ErrDescription); got != c.want {
			t.Errorf("checkStory(%q) = %q, want %q", c.in, got, c.want)
		}
	}
	for name, s := range map[string]string{
		"an image":                    "![the pump](https://imgur.com/p.png)",
		"an image behind zero-width":  "!\u200b[the pump](https://imgur.com/p.png)",
		"an image behind a bidi mark": "!\u202e[the pump](https://imgur.com/p.png)",
		"a tag":                       "<script>alert(1)</script>",
		"an upper-case tag":           "<IMG SRC=x>",
		"a closing tag":               "fine </p>",
		"a comment":                   "visible <!-- hidden from the page -->",
		"a declaration":               "<!DOCTYPE html>",
		"a processing instruction":    "<?php echo 1 ?>",
	} {
		if !panicsWith(func() { checkStory(s, 0, descriptionMax, ErrDescription) }, ErrMarkup) {
			t.Errorf("%s: not refused", name)
		}
	}
	if !panicsWith(func() { checkStory(strings.Repeat("a", descriptionMax+1), 0, descriptionMax, ErrDescription) }, ErrDescription) {
		t.Errorf("a story one character too long: not refused")
	}
}

func TestCheckImage(t *testing.T) {
	const v0 = "QmYwAPJzv5CZsnA625s3Xf2nemtYgPpHdWEz79ojWnPbdG"
	const v1 = "bafybeigdyrzt5sfp7udm7hu76uh7y26nf3efuylqabf3oclgtqy55fbzdi"
	if cid, alt := checkImage("", ""); cid != "" || alt != "" {
		t.Errorf("no photo: got %q, %q", cid, alt)
	}
	for _, cid := range []string{v0, v1} {
		if _, alt := checkImage(cid, "  The village well, dry since March "); alt != "The village well, dry since March" {
			t.Errorf("%s: alt = %q", cid, alt)
		}
	}
	for name, c := range map[string][2]string{
		"alt text without a photo": {"", "a well"},
		"a photo without alt text": {v0, ""},
		"blank alt text":           {v0, "   "},
		"alt text of a space":      {v0, "\ufe0f \ufe0f"},
		"alt text too long":        {v0, strings.Repeat("a", altMax+1)},
		"v0 with a 0":              {"Qm0wAPJzv5CZsnA625s3Xf2nemtYgPpHdWEz79ojWnPbdG", "a well"},
		"v0 too short":             {v0[:45], "a well"},
		"v1 in upper case":         {strings.ToUpper(v1), "a well"},
		"v1 breaking out":          {"bafy](javascript:alert(1))", "a well"},
		"v1 too long":              {"b" + strings.Repeat("a", cidMaxBytes), "a well"},
		"not a CID":                {"https://imgur.com/p.png", "a well"},
	} {
		if !panicsWith(func() { checkImage(c[0], c[1]) }, ErrImage) {
			t.Errorf("%s: not refused", name)
		}
	}
}

package bolo

import "chain/banker"

// CampaignView is a campaign as clients see it (API §2.4): a copy, holding nothing
// of the realm's state, its derived fields computed at now without writing.
type CampaignView struct {
	ID, Title, Description, Category, ImageCID, ImageAlt string
	ImageHidden                                          bool
	Organizer, Beneficiary                               address
	Mode, Status, CloseReason                            string
	Listed                                               bool
	Notice                                               string

	Goal      int64
	Raised    int64
	Refunded  int64
	Withdrawn int64
	NetRaised int64
	Balance   int64
	Untracked int64

	DonorCount, DonationCount, RefundCount, UpdateCount int

	Deposit          int64
	Bond             int64
	BondSlashed      bool
	BondReleasableAt int64

	CreatedAt, Deadline, ClosedAt, LastDonationAt, LastUpdateAt int64

	ClosableByAnyoneAt int64
	ExitOpensAt        int64
	FinalizableAt      int64

	EverWithdrawn bool
	ExitOpen      bool

	EscrowAddress address
	BondAddress   address
	Params        Params
}

// GetCampaign returns campaign id's view (API §4). An unknown or non-canonical ID is
// ErrNotFound (C9).
func GetCampaign(id string) CampaignView {
	return campaignView(campaignOf(id))
}

// campaignOf returns the campaign id names, or panics with ErrNotFound (C9).
func campaignOf(id string) *campaign {
	c, ok := lookup(id)
	if !ok {
		panic(ErrNotFound)
	}
	return c
}

// lookup returns the campaign id names, if id is canonical and the campaign exists.
func lookup(id string) (*campaign, bool) {
	n, ok := parseID(id)
	if !ok {
		return nil, false
	}
	v := campaigns.Get(n.Binary())
	if v == nil {
		return nil, false
	}
	return v.(*campaign), true
}

// effective returns c's status, close reason and close time at now, counting a
// passed deadline as recorded (API §2.4, §3.1), without writing.
func effective(c *campaign) (status, reason string, closedAt int64) {
	s := c.state
	if s.status == statusOpen && c.deadline != 0 && now() >= c.deadline {
		return statusClosed, reasonDeadline, c.deadline
	}
	return s.status, s.closeReason, s.closedAt
}

// trackedBalance is what the books say the escrow holds (API §2.4): 0 in direct
// mode.
func trackedBalance(c *campaign) int64 {
	if c.mode != modeEscrow {
		return 0
	}
	s := c.state
	return s.raised - s.withdrawn - s.refunded
}

// campaignView builds c's view at now (API §2.4).
func campaignView(c *campaign) CampaignView {
	s, p := c.state, c.params
	status, reason, closedAt := effective(c)
	balance := trackedBalance(c)
	untracked := banker.NewReadonlyBanker().GetCoin(escrowAddr(c.id), "ugnot") - balance
	if untracked < 0 {
		untracked = 0
	}
	v := CampaignView{
		ID:          idString(c.id),
		Title:       c.text.title,
		Description: c.text.description,
		Category:    c.category,
		ImageCID:    c.text.imageCID,
		ImageAlt:    c.text.imageAlt,
		ImageHidden: s.imageHidden,
		Organizer:   c.organizer,
		Beneficiary: c.beneficiary,
		Mode:        c.mode,
		Status:      status,
		CloseReason: reason,
		Listed:      s.listed,
		Notice:      s.notice,

		Goal:      c.goal,
		Raised:    s.raised,
		Refunded:  s.refunded,
		Withdrawn: s.withdrawn,
		NetRaised: s.raised - s.refunded,
		Balance:   balance,
		Untracked: untracked,

		DonorCount:    s.donorCount,
		DonationCount: s.donationCount,
		RefundCount:   s.refundCount,
		UpdateCount:   s.updateCount,

		Deposit:     p.CreationDeposit,
		Bond:        s.bond,
		BondSlashed: s.bondSlashed,

		CreatedAt:      c.createdAt,
		Deadline:       c.deadline,
		ClosedAt:       closedAt,
		LastDonationAt: s.lastDonationAt,
		LastUpdateAt:   s.lastUpdateAt,

		EverWithdrawn: s.everWithdrawn,
		EscrowAddress: escrowAddr(c.id),
		BondAddress:   bondAddr(c.id),
		Params:        p,
	}
	switch status {
	case statusOpen:
		v.ClosableByAnyoneAt = dormantAt(c)
		if c.deadline != 0 {
			v.FinalizableAt = finalizableAt(c, c.deadline, balance)
		}
	case statusClosed:
		v.BondReleasableAt = closedAt + p.BondHold
		v.FinalizableAt = finalizableAt(c, closedAt, balance)
	case statusSettled:
		v.BondReleasableAt = closedAt + p.BondHold
	}
	if c.mode == modeEscrow && status != statusOpen {
		v.ExitOpensAt = closedAt + p.ExitDelay
		v.ExitOpen = s.everWithdrawn && balance > 0 && now() >= v.ExitOpensAt
	}
	return v
}

// dormantAt is when anyone may close c for dormancy: its last activity plus its
// snapshot's dormancy period (API §3.1).
func dormantAt(c *campaign) int64 { return lastActivity(c) + c.params.DormancyPeriod }

// lastActivity is the latest of c's creation, its last gift and its last update:
// dormancy counts from it (API §3.1).
func lastActivity(c *campaign) int64 {
	last := c.createdAt
	if c.state.lastDonationAt > last {
		last = c.state.lastDonationAt
	}
	if c.state.lastUpdateAt > last {
		last = c.state.lastUpdateAt
	}
	return last
}

// finalizableAt is when Finalize first succeeds for c closed at closedAt (API §2.4,
// §3.4): at once in direct mode or with nothing tracked, else once the exit opens.
func finalizableAt(c *campaign, closedAt, balance int64) int64 {
	if c.mode == modeDirect || balance == 0 {
		return closedAt
	}
	return closedAt + c.params.ExitDelay
}

package bolo

import (
	"chain"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
)

// testCampaign builds a campaign in memory, stored nowhere: views and the deadline
// helper read only what they are given.
func testCampaign(id seqid.ID, mode string, deadline int64) *campaign {
	return &campaign{
		id: id, category: "water", mode: mode, deadline: deadline, createdAt: now(),
		organizer: testutils.TestAddress("organizer"), beneficiary: testutils.TestAddress("beneficiary"),
		params:        Params{1_000_000, 90 * secondsPerDay, 60 * secondsPerDay, 30 * secondsPerDay},
		text:          &campaignText{title: "Clean water"},
		state:         &campaignState{status: statusOpen, listed: true},
		contributions: avl.NewTree(), receipts: avl.NewTree(), withdrawals: avl.NewTree(),
		refunds: avl.NewTree(), updates: avl.NewTree(),
	}
}

const heightsPerDay = 17280 // five seconds a height (spike S10)

func TestRecordDeadline(cur realm, t *testing.T) {
	c := testCampaign(9001, modeEscrow, now()+secondsPerDay)
	key := c.id.Binary()
	active.Set(key, true)
	activeByCategory.Set("water/"+key, true)
	defer dropActive(c)

	recordDeadline(cur, c)
	if c.state.status != statusOpen || !active.Has(key) {
		t.Fatalf("closed before its deadline")
	}
	testing.SkipHeights(2 * heightsPerDay)
	recordDeadline(cur, c)
	s := c.state
	if s.status != statusClosed || s.closedAt != c.deadline || s.closeReason != reasonDeadline {
		t.Errorf("after the deadline: %s at %d (%s), want closed at the deadline %d", s.status, s.closedAt, s.closeReason, c.deadline)
	}
	if active.Has(key) || activeByCategory.Has("water/"+key) {
		t.Errorf("a closed campaign is still in the active indexes")
	}
	// A second call changes nothing.
	s.closeReason = reasonOrganizer
	recordDeadline(cur, c)
	if s.closeReason != reasonOrganizer {
		t.Errorf("recordDeadline rewrote a closed campaign")
	}
}

func TestCampaignView(t *testing.T) {
	// Live Params unlike every test campaign's snapshot: a view reading them would
	// show it (INV-5).
	defer func(p Params) { params = p }(params)
	params = Params{CreationDeposit: 7, DormancyPeriod: 1, ExitDelay: 2, BondHold: 3}

	// Open, no deadline: only dormancy has a time.
	c := testCampaign(9002, modeEscrow, 0)
	c.state.lastDonationAt = now() + 5
	v := campaignView(c)
	if v.Status != statusOpen || v.ClosableByAnyoneAt != now()+5+c.params.DormancyPeriod ||
		v.FinalizableAt != 0 || v.ExitOpensAt != 0 || v.BondReleasableAt != 0 || v.ExitOpen {
		t.Errorf("open, no deadline: %v", v)
	}

	// Open with a deadline: finalizable at the deadline while nothing is tracked,
	// once the exit opens when something is.
	d := testCampaign(9003, modeEscrow, now()+10*secondsPerDay)
	if v := campaignView(d); v.FinalizableAt != d.deadline {
		t.Errorf("open, nothing tracked: FinalizableAt = %d, want %d", v.FinalizableAt, d.deadline)
	}
	d.state.raised = 500
	if v := campaignView(d); v.Balance != 500 || v.NetRaised != 500 || v.FinalizableAt != d.deadline+d.params.ExitDelay {
		t.Errorf("open, 500 tracked: %v", v)
	}

	// Past the deadline: closed at it, without a write.
	testing.SkipHeights(11 * heightsPerDay)
	v = campaignView(d)
	if v.Status != statusClosed || v.CloseReason != reasonDeadline || v.ClosedAt != d.deadline {
		t.Errorf("past the deadline: %s, %s, %d", v.Status, v.CloseReason, v.ClosedAt)
	}
	if d.state.status != statusOpen {
		t.Errorf("a view wrote the close")
	}
	if v.ClosableByAnyoneAt != 0 || v.BondReleasableAt != d.deadline+d.params.BondHold ||
		v.ExitOpensAt != d.deadline+d.params.ExitDelay || v.FinalizableAt != v.ExitOpensAt || v.ExitOpen {
		t.Errorf("closed, never withdrawn: %v", v)
	}

	// The exit window opens only after a withdrawal, once its delay has passed.
	d.state.everWithdrawn = true
	if campaignView(d).ExitOpen {
		t.Errorf("exit open before its delay")
	}
	testing.SkipHeights(61 * heightsPerDay)
	if !campaignView(d).ExitOpen {
		t.Errorf("exit not open after its delay")
	}
	d.state.everWithdrawn = false
	if campaignView(d).ExitOpen {
		t.Errorf("exit open after its delay without any withdrawal")
	}
	// Nor once everything tracked was withdrawn: there is nothing to reclaim.
	d.state.everWithdrawn, d.state.withdrawn = true, d.state.raised
	if campaignView(d).ExitOpen {
		t.Errorf("exit open on an emptied escrow")
	}

	// Direct mode: nothing tracked, no exit, finalizable at the close.
	e := testCampaign(9004, modeDirect, now()+secondsPerDay)
	e.state.raised = 700
	testing.SkipHeights(2 * heightsPerDay)
	if v := campaignView(e); v.Balance != 0 || v.NetRaised != 700 || v.ExitOpensAt != 0 || v.FinalizableAt != e.deadline {
		t.Errorf("direct, closed: %v", v)
	}

	// Settled: nothing left to finalize; the bond's release time stays.
	e.state.status, e.state.closedAt, e.state.closeReason = statusSettled, e.deadline, reasonDeadline
	if v := campaignView(e); v.FinalizableAt != 0 || v.BondReleasableAt != e.deadline+e.params.BondHold {
		t.Errorf("settled: %v", v)
	}

	// Untracked: what the escrow holds beyond the books, never below 0.
	f := testCampaign(9005, modeEscrow, 0)
	f.state.raised = 300
	testing.IssueCoins(escrowAddr(f.id), chain.NewCoins(chain.NewCoin("ugnot", 1000)))
	if v := campaignView(f); v.Untracked != 700 {
		t.Errorf("Untracked = %d, want 700", v.Untracked)
	}
	f.state.raised = 5000
	if v := campaignView(f); v.Untracked != 0 {
		t.Errorf("Untracked = %d, want 0 when the books exceed the bank", v.Untracked)
	}
}

package bolo

// adminAddr is the registry's admin (API §3.7, §3.6): a constant in source, never
// the deployer.
//
// Until the real admin key exists, it is an address nobody holds a key for, so a
// deployment made by mistake has no admin at all. Tests and local runs stage the
// realm with a test admin instead (internal/stage).
const adminAddr address = "g1at2h7kdhz2m9lv6azn54mwu4wl95k94wu90uwj"

// Package bolo is Bolo's version registry (API §3.7): it tells clients which
// version new campaigns start on. Every version lives at its own path,
// gno.land/r/g12yg9nh4ncma44emgm8msxe8aavzywt0p95tanv/bolo/vN, and keeps its campaigns and their money for good (ADR
// D14); the registry holds no money and only points.
package bolo

package bolo

// Error is the type of every failure the registry reports (API C10, §7). Each one is
// a constant led by its copy key, the same keys v0 uses (UI spec §8).
type Error string

func (e Error) Error() string { return string(e) }

const (
	ErrNotUserCall Error = "err.use_wallet: not a direct transaction from a wallet"
	ErrSessionKey  Error = "err.master_key: a session key can't do this"
	ErrNotAdmin    Error = "err.not_allowed: only the admin can do this"
	ErrSetting     Error = "err.input: invalid setting"
)

package bolo

import (
	"strings"
	"testing"
)

// Each error and its copy key, as API §7 pairs them for the registry.
var errorKeys = map[Error]string{
	ErrNotUserCall: "err.use_wallet",
	ErrSessionKey:  "err.master_key",
	ErrNotAdmin:    "err.not_allowed",
	ErrSetting:     "err.input",
}

// TestErrorsLeadWithCopyKeys: every error starts with its own copy key, then ": "
// and a message (API C10).
func TestErrorsLeadWithCopyKeys(t *testing.T) {
	if len(errorKeys) != 4 {
		t.Errorf("%d errors, API §7 gives the registry 4", len(errorKeys))
	}
	for e, want := range errorKeys {
		key, msg, ok := strings.Cut(string(e), ": ")
		if !ok || key != want || msg == "" {
			t.Errorf("%q doesn't start with %s", string(e), want)
		}
	}
}

package bolo

import (
	"chain"
	"chain/runtime"
)

// assertCurrent is the first statement of every crossing function (API C2).
func assertCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("bolo registry: not the current realm")
	}
}

// assertCodeCaller refuses any caller but a deployed realm (API C11). A maketx run
// script is ephemeral and code at once: it is refused here, as is a user.
func assertCodeCaller(cur realm) {
	if p := cur.Previous(); !p.IsCode() || p.IsEphemeral() {
		panic(ErrNotUserCall)
	}
}

// assertSigner runs right after C11's branch in every write: no session key, in
// either branch (C11), then the caller must be who (API §3.7).
func assertSigner(cur realm, who address) {
	if _, _, _, isSession := runtime.GetSessionInfo(); isSession {
		panic(ErrSessionKey)
	}
	if cur.Previous().Address() != who {
		panic(ErrNotAdmin)
	}
}

// checkCandidate refuses, with ErrSetting, a malformed address (C12: exactly 40
// characters, a lowercase "g" first, then IsValid) and the registry's own address
// and storage-deposit address, which can never accept the admin role (API §3.7).
func checkCandidate(a address) {
	if len(a) != 40 || a[0] != 'g' || !a.IsValid() {
		panic(ErrSetting)
	}
	if a == chain.PackageAddress(registryPath) || a == chain.DeriveStorageDepositAddr(registryPath) {
		panic(ErrSetting)
	}
}

package bolo

// init refuses to deploy the registry from its admin's own key (API §3.7, §3.6, ADR
// D11): the key that deploys under the namespace must not also be the admin, or one
// stolen key could deploy a malicious version and point the registry at it.
func init(cur realm) {
	if cur.Previous().Address() == adminAddr {
		panic("bolo registry: the admin key may not deploy the registry; deploy from the namespace key, which must not be the admin")
	}
}

package bolo

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	registryPath  = "gno.land/r/g12yg9nh4ncma44emgm8msxe8aavzywt0p95tanv/bolo"
	versionPrefix = registryPath + "/v"

	// maxVersions keeps Versions() to one bounded read (INV-9).
	maxVersions = 50

	// maxPathLen is the longest package path the chain deploys: a longer one could
	// never hold a version.
	maxPathLen = 256
)

// The registry's state (API §3.7), all unexported (C6).
var (
	admin        address = adminAddr // a realm once a DAO accepts the role (ADR D11)
	pendingAdmin address             // the proposed admin until it accepts; "" for none

	versions []string // every version added, oldest first
	added    avl.Tree // path → true, for lookups
	current  string   // "" until the first SetCurrent
)

// The registry's events (API §6).
const (
	evVersionAdded  = "VersionAdded"
	evCurrentSet    = "CurrentSet"
	evAdminProposed = "AdminProposed"
	evAdminChanged  = "AdminChanged"
)

// Current returns the version new campaigns should use: a pkgpath, or "" before the
// first SetCurrent.
func Current() string { return current }

// Versions returns every version ever added, oldest first, as a copy.
func Versions() []string { return append([]string(nil), versions...) }

// GetAdmin returns the admin and the proposed admin, "" when there is none.
func GetAdmin() (address, address) { return admin, pendingAdmin }

// AddVersion registers a version. None is ever removed.
func AddVersion(cur realm, path string) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	checkNewVersion(path)
	added.Set(path, true)
	versions = append(versions, path)
	chain.Emit(evVersionAdded, "path", path)
}

// SetCurrent points new campaigns, and their donors' money, at a version already
// added.
func SetCurrent(cur realm, path string) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	if !added.Has(path) {
		panic(ErrSetting)
	}
	current = path
	chain.Emit(evCurrentSet, "path", path)
}

// ProposeAdmin proposes next as the registry's admin, who takes over by accepting.
// A second proposal replaces the first.
func ProposeAdmin(cur realm, next address) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, admin)
	checkCandidate(next)
	pendingAdmin = next
	chain.Emit(evAdminProposed, "next", next.String())
}

// AcceptAdmin makes the proposed admin the admin, and ends the proposal.
func AcceptAdmin(cur realm) {
	assertCurrent(cur)
	if cur.Previous().IsUserCall() {
		runtime.AssertOriginCall()
	} else {
		assertCodeCaller(cur)
	}
	assertSigner(cur, pendingAdmin)
	previous := admin
	admin, pendingAdmin = pendingAdmin, ""
	chain.Emit(evAdminChanged, "admin", admin.String(), "previous", previous.String())
}

// Render is Bolo's front page on gnoweb, the twin of the web app's Home (UI spec §3,
// §4.13): the name, the tagline, a link to the current version, then the versions,
// oldest first, the current one marked. It ignores path: nothing a visitor types
// reaches the page (API §3.7).
func Render(path string) string {
	if len(versions) == 0 {
		return "# Bolo\n\nNo version is registered yet.\n"
	}
	var b strings.Builder
	b.WriteString("# Bolo\n\nGive together. See where it goes.\n\n")
	if current != "" {
		b.WriteString("**[Open Bolo](" + strings.TrimPrefix(current, "gno.land") + ")**, where new campaigns start.\n\n")
	}
	b.WriteString("## Versions\n\nEach campaign runs to its end on the version it started on: money never moves between versions.\n\n")
	for _, v := range versions {
		b.WriteString("- [" + v + "](" + strings.TrimPrefix(v, "gno.land") + ")")
		if v == current {
			b.WriteString(" — current")
		}
		b.WriteString("\n")
	}
	return b.String()
}

// checkNewVersion refuses, with ErrSetting, a path that isn't a version path, one
// already added, and one past the cap (API §3.7).
func checkNewVersion(path string) {
	if !isVersionPath(path) || added.Has(path) || len(versions) >= maxVersions {
		panic(ErrSetting)
	}
}

// isVersionPath reports whether path names a Bolo version (API §3.7), parsed by
// hand: exactly versionPrefix, then 0 or a number without a leading zero, and
// nothing else, in at most maxPathLen bytes. v012 would be another package than
// v12, so it is refused.
func isVersionPath(path string) bool {
	if len(path) > maxPathLen || !strings.HasPrefix(path, versionPrefix) {
		return false
	}
	n := path[len(versionPrefix):]
	if n == "" || (n[0] == '0' && len(n) > 1) {
		return false
	}
	for i := 0; i < len(n); i++ {
		if n[i] < '0' || n[i] > '9' {
			return false
		}
	}
	return true
}

package bolo

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
